    first_seven_payload_bytes = sum(
        len(frame["payload"]) for frame in payload_frames
    )
    if (
        first_seven_payload_bytes != 12_633_816
        or first_seven_payload_bytes <= 12 * 1024 * 1024
    ):
        raise AssertionError("training payload volume drifted")

    # This is one synthetic exact-current worker receipt. The manifest
