def _binary32(value: float) -> float:
    return struct.unpack("<f", struct.pack("<f", value))[0]


class _TorchMt19937Fixture:
    """Independent stdlib reproduction of Torch's CPU MT19937 engine."""

    def __init__(self, seed: int):
        self.state = [0] * 624
        self.state[0] = seed & 0xFFFFFFFF
        for index in range(1, 624):
            previous = self.state[index - 1]
            self.state[index] = (
                1812433253
                * (previous ^ (previous >> 30))
                + index
            ) & 0xFFFFFFFF
        self.index = 624

    def _next_state(self) -> None:
        for index in range(624):
            mixed = (
                (self.state[index] & 0x80000000)
                | (self.state[(index + 1) % 624] & 0x7FFFFFFF)
            )
            self.state[index] = (
                self.state[(index + 397) % 624]
                ^ (mixed >> 1)
                ^ (0x9908B0DF if mixed & 1 else 0)
            )
        self.index = 0

    def random_uint32(self) -> int:
        if self.index == 624:
            self._next_state()
        value = self.state[self.index]
        self.index += 1
        value ^= value >> 11
        value ^= (value << 7) & 0x9D2C5680
        value ^= (value << 15) & 0xEFC60000
        value ^= value >> 18
        return value & 0xFFFFFFFF

    def uniform_float32_bytes(
        self,
        count: int,
        bound: float,
    ) -> bytes:
        # The CPU kernel first converts its bounds to the tensor's float32
        # dtype. Arm64 evaluates the multiply-add with one final float32
        # rounding; exact binary64 arithmetic reproduces that fused result.
        rounded_bound = _binary32(bound)
        lower = -rounded_bound
        upper = rounded_bound
        raw = bytearray()
        for _ in range(count):
            unit = (
                self.random_uint32() & 0xFFFFFF
            ) * (1.0 / 16777216.0)
            value = _binary32(unit * (upper - lower) + lower)
            raw.extend(struct.pack("<f", value))
        return bytes(raw)


