def _well_formed_raw_hash_trace_mutation_fixture(bundle: dict) -> bytes:
    rows = copy.deepcopy(bundle["trace_rows"])
    target = rows[100]
    if target["profile"]["rollout_seconds"] != 0.25:
        raise AssertionError("raw-hash mutation precondition drifted")
    target["profile"]["rollout_seconds"] = 0.24
    raw = b"".join(_canonical_json_fixture(row) for row in rows)
    if len(raw) != len(bundle["trace_bytes"]):
        raise AssertionError("raw-hash mutation changed payload length")
    if raw == bundle["trace_bytes"]:
        raise AssertionError("raw-hash mutation did not change payload")
    return raw


def _wilson95_fixture(successes: int, episodes: int) -> list[float]:
    z = 1.959963984540054
    p = successes / episodes
    denominator = 1.0 + z * z / episodes
    center = (p + z * z / (2.0 * episodes)) / denominator
    margin = z * math.sqrt(
        p * (1.0 - p) / episodes
        + z * z / (4.0 * episodes * episodes)
    ) / denominator
    return [
        max(0.0, center - margin),
        min(1.0, center + margin),
    ]


def _prefix_success_bitset(successes: int) -> bytes:
    raw = bytearray(4096)
    for index in range(successes):
        raw[index // 8] |= 1 << (index % 8)
    return bytes(raw)


def _bitset_semantic_sha256_fixture(
    *,
    update: int,
    seed_index: int,
    action_seed: int,
    repeat_flag: int,
    raw: bytes,
) -> str:
    return hashlib.sha256(
        b"f5-success-bitset-v1\0"
        + struct.pack(">I", update)
        + struct.pack(">I", seed_index)
        + struct.pack(">I", action_seed)
        + struct.pack(">Q", 32768)
        + bytes((repeat_flag,))
        + raw
    ).hexdigest()


