class _RealDarwinLeafPublicationIO:
    def __init__(
        self,
        protocol,
        libc,
        directory,
        *,
        destination_basename,
        payload,
    ):
        self.protocol = protocol
        self.libc = libc
        self.directory = pathlib.Path(directory)
        self.destination_basename = destination_basename
        self.temporary_basename = "leaf.tmp"
        self.payload = payload
        self.directory_fd = os.open(
            self.directory,
            os.O_RDONLY | os.O_DIRECTORY,
        )
        self.temporary_fd = None
        self.destination_fd = None
        self.temporary_identity = None
        self.events = []

    def close(self):
        _close_fd(self.destination_fd)
        self.destination_fd = None
        _close_fd(self.temporary_fd)
        self.temporary_fd = None
        _close_fd(self.directory_fd)
        self.directory_fd = None

    def validate_payload_semantics(
        self,
        relative_path,
        payload,
        semantic_sha256,
    ):
        self.events.append("validate_payload_semantics")
        expected_semantic = hashlib.sha256(
            b"f5-canonical-json-v1\0" + self.payload
        ).hexdigest()
        try:
            decoded = json.loads(self.payload)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise AssertionError("payload is not canonical JSON") from error
        if (
            relative_path != self.destination_basename
            or payload != self.payload
            or payload != _canonical_json_fixture(decoded)
            or semantic_sha256 != expected_semantic
        ):
            raise AssertionError("real payload semantic identity mismatch")

    def validate_checkpoint_semantics(
        self,
        update,
        raw_checkpoint,
        tensor_sha256,
    ):
        self.events.append("validate_checkpoint_semantics")
        if (
            update != 0
            or raw_checkpoint != self.payload
            or len(raw_checkpoint) != 879900
            or tensor_sha256
            != _canonical_tensor_sha256_from_raw_fixture(raw_checkpoint)
        ):
            raise AssertionError(
                "real checkpoint semantic identity mismatch"
            )

    def create_temporary_new(self, *args, **kwargs):
        self.events.append("create_temporary_new")
        self.temporary_fd = os.open(
            self.temporary_basename,
            (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_NOFOLLOW", 0)
            ),
            0o600,
            dir_fd=self.directory_fd,
        )
        self.temporary_identity = os.fstat(self.temporary_fd)

    def fchmod_temporary_0600(self, *args, **kwargs):
        self.events.append("fchmod_temporary_0600")
        os.fchmod(self.temporary_fd, 0o600)

    def require_temporary_no_acl(self, *args, **kwargs):
        self.events.append("require_temporary_no_acl")
        self.protocol.require_no_extended_acl(
            self.libc,
            self.temporary_fd,
        )

    def write_all(self, *args, **kwargs):
        self.events.append("write_all")
        remaining = memoryview(self.payload)
        while remaining:
            written = os.write(self.temporary_fd, remaining)
            if written <= 0:
                raise AssertionError("real fixture write made no progress")
            remaining = remaining[written:]

    def flush_temporary(self, *args, **kwargs):
        self.events.append("flush_temporary")

    def fsync_temporary_file(self, *args, **kwargs):
        self.events.append("fsync_temporary_file")
        os.fsync(self.temporary_fd)

    def _require_parent_identity(self):
        path_stat = self.directory.stat()
        descriptor_stat = os.fstat(self.directory_fd)
        if (
            path_stat.st_dev,
            path_stat.st_ino,
            path_stat.st_mode,
        ) != (
            descriptor_stat.st_dev,
            descriptor_stat.st_ino,
            descriptor_stat.st_mode,
        ):
            raise AssertionError("directory path/descriptor identity changed")

    def validate_parent_path_before(self, *args, **kwargs):
        self.events.append("validate_parent_path_before")
        self._require_parent_identity()

    def require_destination_absent_nofollow(self, *args, **kwargs):
        self.events.append("require_destination_absent_nofollow")
        try:
            os.stat(
                self.destination_basename,
                dir_fd=self.directory_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return
        raise FileExistsError(errno.EEXIST, "destination exists")

    def validate_source_name_identity(self, *args, **kwargs):
        self.events.append("validate_source_name_identity")
        named = os.stat(
            self.temporary_basename,
            dir_fd=self.directory_fd,
            follow_symlinks=False,
        )
        held = os.fstat(self.temporary_fd)
        if (
            named.st_dev,
            named.st_ino,
            named.st_mode,
            named.st_nlink,
            named.st_size,
        ) != (
            held.st_dev,
            held.st_ino,
            held.st_mode,
            held.st_nlink,
            held.st_size,
        ):
            raise AssertionError("temporary source identity changed")

    def rename_exclusive(self, *args, **kwargs):
        self.events.append("rename_exclusive")
        self.protocol.exclusive_rename_new(
            self.libc,
            self.directory_fd,
            self.temporary_basename,
            self.directory_fd,
            self.destination_basename,
        )

    def validate_parent_path_after(self, *args, **kwargs):
        self.events.append("validate_parent_path_after")
        self._require_parent_identity()

    def reopen_destination_nofollow(self, *args, **kwargs):
        self.events.append("reopen_destination_nofollow")
        self.destination_fd = os.open(
            self.destination_basename,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=self.directory_fd,
        )
        return self.destination_fd

    def validate_destination_identity(self, *args, **kwargs):
        self.events.append("validate_destination_identity")
        destination = os.fstat(self.destination_fd)
        source = self.temporary_identity
        if (
            destination.st_dev,
            destination.st_ino,
            destination.st_mode & 0o777,
            destination.st_nlink,
            destination.st_size,
        ) != (
            source.st_dev,
            source.st_ino,
            0o600,
            1,
            len(self.payload),
        ):
            raise AssertionError("published leaf identity mismatch")
        observed = b""
        while len(observed) < len(self.payload):
            chunk = os.read(
                self.destination_fd,
                len(self.payload) - len(observed),
            )
            if not chunk:
                break
            observed += chunk
        if observed != self.payload:
            raise AssertionError("published leaf bytes mismatch")

    def require_destination_no_acl(self, *args, **kwargs):
        self.events.append("require_destination_no_acl")
        self.protocol.require_no_extended_acl(
            self.libc,
            self.destination_fd,
        )

    def fsync_containing_directory(self, *args, **kwargs):
        self.events.append("fsync_containing_directory")
        os.fsync(self.directory_fd)


def _prepared_puffer_smoke_unavailability(
    puffer_root: pathlib.Path,
) -> str | None:
    if sys.platform != "darwin":
        return "frozen prepared-Puffer smoke requires Darwin"
    if platform.machine() != "arm64":
        return "frozen prepared-Puffer smoke requires arm64"
    if platform.mac_ver()[0] != "15.6":
        return "frozen prepared-Puffer smoke requires macOS 15.6"
    if os.uname().release != "24.6.0":
        return "frozen prepared-Puffer smoke requires Darwin 24.6.0"
    model = subprocess.run(
        ["/usr/sbin/sysctl", "-n", "hw.model"],
        check=False,
        capture_output=True,
        text=True,
    )
    if model.returncode != 0 or model.stdout.strip() != "Mac16,7":
        return "frozen prepared-Puffer smoke requires Mac16,7"

    root = puffer_root.resolve()
    if not root.is_dir():
        return "prepared Puffer root is absent"
    head = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "HEAD"],
        check=False,
        capture_output=True,
        text=True,
    )
    if (
        head.returncode != 0
        or head.stdout.strip()
        != "9836f0d2e78889c1aaf189c04d161b6fc61a9386"
    ):
        return "prepared Puffer root does not have the frozen base commit"
    status = subprocess.run(
        [
            "/usr/bin/env",
            "-i",
            "PATH=/usr/bin:/bin",
            "LANG=C",
            "LC_ALL=C",
            "git",
            "-C",
            str(root),
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
        ],
        check=False,
        capture_output=True,
    )
    if status.returncode != 0 or status.stderr:
        return "prepared Puffer status command is unavailable"
    if len(status.stdout) != 3437:
        return "prepared Puffer status byte count is not frozen"
    if hashlib.sha256(
        b"bloodbowl-f5-git-status-v1\0" + status.stdout
    ).hexdigest() != (
        "60ff30fe6d00bd26ff2e7b2c041b44db2f1cade0dc3577c13e070dc7a7de57f2"
    ):
        return "prepared Puffer status digest is not frozen"

    module = root / "pufferlib/_C.cpython-312-darwin.so"
    if not module.is_file() or module.is_symlink():
        return "qualified F5 compiled module is absent"
    if hashlib.sha256(module.read_bytes()).hexdigest() != (
        "0dd03bcf444f84241ef8f6724b5e7d1e8c572c56d66714ccd44c1f5be69f1488"
    ):
        return "qualified F5 compiled module digest is not frozen"

    interpreter = root / ".venv/bin/python3.12"
    if not interpreter.exists():
        return "prepared CPython 3.12 interpreter is absent"
    if hashlib.sha256(interpreter.resolve().read_bytes()).hexdigest() != (
        "d4706f4e64be2b6f94083b270a529469955f56d2438c03182427209fbbb65752"
    ):
        return "prepared CPython executable digest is not frozen"
    source_hashes = {
        "pufferlib/pufferl.py": (
            "22bbbe209f5d73a397863b15ecb5e76af0617143bf8bf7158381f560f957526c"
        ),
        "pufferlib/torch_pufferl.py": (
            "30e36f98951b7c38541156835f83c06e6a8b3b475b65349812313825da36daec"
        ),
        "pufferlib/models.py": (
            "def01bf10ce48eabe9743a9dfb4d5ad635c214e14b07219e5c929b6ae61afd59"
        ),
        "pufferlib/muon.py": (
            "105bfc542cdb125e384a3290f7d282b212379836bc9983290948b12b860ba888"
        ),
        "config/default.ini": (
            "6b129902269d99e5434a47a175e3ac4c13f30af4e4da613ebe158b02cd5bd9cc"
        ),
        "config/bloodbowl.ini": (
            "7ef064026b2d098d42d12c7ca67e1dd5b8ae3c4d584f788c03916a7d6bd08f1e"
        ),
    }
    for relative, expected_sha256 in source_hashes.items():
        path = root / relative
        if (
            not path.is_file()
            or path.is_symlink()
            or hashlib.sha256(path.read_bytes()).hexdigest()
            != expected_sha256
        ):
            return f"prepared Puffer source drifted: {relative}"
    probe = subprocess.run(
        [
            str(interpreter),
            "-B",
            "-s",
            "-P",
            "-c",
            (
                "import json,sys,torch;"
                "print(json.dumps({"
                "'python':sys.version.split()[0],"
                "'torch':torch.__version__,"
                "'torch_git':torch.version.git_version"
                "},sort_keys=True,separators=(',',':')))"
            ),
        ],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    if probe.returncode != 0 or probe.stderr:
        return "prepared Python/Torch runtime probe failed"
    try:
        runtime = json.loads(probe.stdout)
    except json.JSONDecodeError:
        return "prepared Python/Torch runtime probe was not JSON"
    if runtime != {
        "python": "3.12.12",
        "torch": "2.9.1",
        "torch_git": "5811a8d7da873dd699ff6687092c225caffcf1bb",
    }:
        return "prepared Python/Torch runtime identity is not frozen"
    return None


def _exact_final_consumer_unavailability() -> str | None:
    if sys.platform != "darwin":
        return "exact final consumer requires the frozen Darwin host"
    if platform.machine() != "arm64":
        return "exact final consumer requires arm64"
    if platform.mac_ver()[0] != "15.6":
        return "exact final consumer requires macOS 15.6"
    if os.uname().release != "24.6.0":
        return "exact final consumer requires Darwin 24.6.0"
    model = subprocess.run(
        ["/usr/sbin/sysctl", "-n", "hw.model"],
        check=False,
        capture_output=True,
    )
    if (
        model.returncode != 0
        or model.stderr
        or model.stdout.strip() != b"Mac16,7"
    ):
        return "exact final consumer requires Mac16,7"
    identities = (
        (
            pathlib.Path("/usr/bin/env"),
            (
                "7259ae24c7f1907eede9230ddc3c6b44e"
                "811c64f9ccc0073681d560094e092f0"
            ),
        ),
        (
            pathlib.Path("/usr/bin/python3"),
            (
                "7588ceab299393618d6f8861502ac0588"
                "d1594025f301d9a61a898215b5571d3"
            ),
        ),
    )
    for path, expected in identities:
        if not path.is_file() or hashlib.sha256(
            path.read_bytes()
        ).hexdigest() != expected:
            return "exact final-consumer executable identity is absent"
    probe = subprocess.run(
        [
            "/usr/bin/python3",
            "-B",
            "-I",
            "-S",
            "-c",
            (
                "import json,sys;"
                "print(json.dumps({"
                "'version':sys.version.split()[0],"
                "'isolated':sys.flags.isolated,"
                "'ignore_environment':sys.flags.ignore_environment,"
                "'no_site':sys.flags.no_site,"
                "'executable':sys.executable,"
                "'path':sys.path},sort_keys=True))"
            ),
        ],
        check=False,
        capture_output=True,
    )
    if probe.returncode != 0 or probe.stderr:
        return "exact final-consumer CPython probe failed"
    try:
        observed = json.loads(probe.stdout)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return "exact final-consumer CPython probe was malformed"
    if (
        observed["version"] != "3.9.6"
        or observed["isolated"] != 1
        or observed["ignore_environment"] != 1
        or observed["no_site"] != 1
        or len(observed["path"]) != 3
    ):
        return "exact final-consumer CPython flags are absent"
    resolved_executable = pathlib.Path(observed["executable"])
    if (
        not resolved_executable.is_file()
        or hashlib.sha256(
            resolved_executable.read_bytes()
        ).hexdigest()
        != (
            "e7276a0ac27acdd53135450bd3038e8a6"
            "d77aad9df9ee06b05ef311ce9955db9"
        )
    ):
        return "exact resolved Xcode CPython identity is absent"
    return None


