def _validate_prepared_one_update_smoke_receipt(
    receipt: dict,
    *,
    manifest: dict,
    puffer_root: pathlib.Path,
) -> None:
    expected_keys = {
        "arguments",
        "call_order",
        "create_vec",
        "digests",
        "initial_raw_checkpoint",
        "model",
        "module_sha256",
        "puffer_commit",
        "puffer_root",
        "puffer_source_manifest_sha256",
        "pufferl",
        "post_update_raw_checkpoint",
        "runtime",
        "schema",
        "seeding",
        "update",
    }
    if set(receipt) != expected_keys:
        raise AssertionError("prepared smoke receipt root is not closed")
    arguments = manifest["puffer"]["arguments"]
    if receipt["schema"] != "bloodbowl-f5-one-update-smoke-v1":
        raise AssertionError("prepared smoke schema drifted")
    if pathlib.Path(receipt["puffer_root"]).resolve() != puffer_root.resolve():
        raise AssertionError("prepared smoke did not consume requested root")
    if (
        receipt["puffer_commit"]
        != "9836f0d2e78889c1aaf189c04d161b6fc61a9386"
    ):
        raise AssertionError("prepared smoke Puffer commit drifted")
    if receipt["module_sha256"] != (
        "0dd03bcf444f84241ef8f6724b5e7d1e8c572c56d66714ccd44c1f5be69f1488"
    ):
        raise AssertionError("prepared smoke module digest drifted")
    if receipt["puffer_source_manifest_sha256"] != (
        "961915f4caf5e0767ce8caaf6ae6e2623bfa3591befcb2913ba5eac561d82f2b"
    ):
        raise AssertionError("prepared smoke Puffer source manifest drifted")
    if receipt["arguments"] != arguments:
        raise AssertionError("prepared smoke effective arguments drifted")
    if receipt["create_vec"] != {
        "arguments": {
            "env": arguments["env"],
            "vec": arguments["vec"],
        },
        "gpu": 0,
    }:
        raise AssertionError("prepared smoke create_vec wiring drifted")
    model = receipt["model"]
    if set(model) != {
        "action_head_count",
        "action_logit_count",
        "construction_order",
        "decoder_act_sizes",
        "encoder_obs_size",
        "hidden_size",
        "network_kwargs",
        "trainable_parameters",
    }:
        raise AssertionError("prepared smoke model receipt is not closed")
    if model["construction_order"] != [
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
    ]:
        raise AssertionError("prepared smoke construction order drifted")
    if model["network_kwargs"] != {
        "expansion_factor": 1,
        "hidden_size": 64,
        "num_layers": 1,
    }:
        raise AssertionError("prepared smoke MinGRU arguments drifted")
    if model["encoder_obs_size"] != 2782:
        raise AssertionError("prepared smoke encoder obs size drifted")
    if model["hidden_size"] != 64:
        raise AssertionError("prepared smoke hidden size drifted")
    if model["action_head_count"] != 3:
        raise AssertionError("prepared smoke action-head count drifted")
    if (
        type(model["decoder_act_sizes"]) is not list
        or len(model["decoder_act_sizes"]) != 3
        or any(
            type(value) is not int or value <= 0
            for value in model["decoder_act_sizes"]
        )
        or sum(model["decoder_act_sizes"]) != 454
        or model["action_logit_count"] != 454
    ):
        raise AssertionError("prepared smoke decoder action sizes drifted")
    if model["trainable_parameters"] != 219975:
        raise AssertionError("prepared smoke parameter count drifted")
    if receipt["pufferl"] != {
        "arguments_sha256": EXPECTED_EFFECTIVE_ARGUMENTS_SHA256,
        "verbose": False,
    }:
        raise AssertionError("prepared smoke PuffeRL wiring drifted")
    if receipt["seeding"] != {
        "evaluation_construction": 38865036,
        "model_initialization": 1937413891,
        "numpy_process": 3265398457,
        "python_process": 249709497,
        "training_torch": 2415287173,
    }:
        raise AssertionError("prepared smoke seed values drifted")
    if receipt["runtime"] != {
        "cuda_selected": False,
        "deterministic_algorithms": True,
        "device": "cpu",
        "interop_threads": 1,
        "intraop_threads": 4,
        "omp_dynamic": "FALSE",
        "omp_num_threads": "4",
        "python_version": "3.12.12",
        "torch_git_revision": (
            "5811a8d7da873dd699ff6687092c225caffcf1bb"
        ),
        "torch_version": "2.9.1",
        "vec_num_threads": 20,
        "worker_environment": EXPECTED_WORKER_ENVIRONMENT,
        "worker_environment_sha256": (
            "de1e11609f4c0bec54a69894149f0200a3a41d94352fac3eb529b1290a0015da"
        ),
    }:
        raise AssertionError("prepared smoke runtime wiring drifted")
    if receipt["update"] != {
        "accepted_global_agent_step": 32768,
        "committed_epoch": 1,
        "full_schedule_updates": 2956,
        "gate_before_train": True,
        "minibatches": 1,
        "rollouts_returned_none": True,
        "stopped_after_updates": 1,
        "tail_valid_after_train": False,
    }:
        raise AssertionError("prepared smoke update receipt drifted")
    if receipt["digests"] != {
        "duplicate_initial_canonical_sha256": (
            EXPECTED_INITIAL_PARAMETER_SHA256
        ),
        "initial_canonical_sha256": EXPECTED_INITIAL_PARAMETER_SHA256,
        "initial_raw_sha256": EXPECTED_INITIAL_RAW_SHA256,
        "post_update_canonical_sha256": (
            EXPECTED_ONE_UPDATE_PARAMETER_SHA256
        ),
        "post_update_raw_sha256": EXPECTED_ONE_UPDATE_RAW_SHA256,
    }:
        raise AssertionError("prepared smoke tensor digests drifted")
    initial_raw = receipt["initial_raw_checkpoint"]
    post_update_raw = receipt["post_update_raw_checkpoint"]
    if (
        type(initial_raw) is not bytes
        or len(initial_raw) != 879900
        or hashlib.sha256(initial_raw).hexdigest()
        != EXPECTED_INITIAL_RAW_SHA256
        or _canonical_tensor_sha256_from_raw_fixture(initial_raw)
        != EXPECTED_INITIAL_PARAMETER_SHA256
    ):
        raise AssertionError(
            "prepared smoke did not return the exact initial raw tensors"
        )
    if (
        type(post_update_raw) is not bytes
        or len(post_update_raw) != 879900
        or hashlib.sha256(post_update_raw).hexdigest()
        != EXPECTED_ONE_UPDATE_RAW_SHA256
        or _canonical_tensor_sha256_from_raw_fixture(post_update_raw)
        != EXPECTED_ONE_UPDATE_PARAMETER_SHA256
    ):
        raise AssertionError(
            "prepared smoke did not return the exact post-update raw tensors"
        )
    if receipt["call_order"] != [
        "random.seed:249709497",
        "numpy.random.seed:3265398457",
        "torch.manual_seed:1937413891",
        "torch.use_deterministic_algorithms:true",
        "torch.set_num_threads:4",
        "torch.set_num_interop_threads:1",
        "_C.create_vec:gpu=0",
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
        "torch.manual_seed:1937413891",
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
        "PuffeRL:verbose=false",
        "torch.manual_seed:2415287173",
        "rollouts",
        "validate_live_rollout",
        "train",
    ]:
        raise AssertionError("prepared smoke direct call order drifted")


def _run_prepared_puffer_duplicate_one_update_smoke(
    puffer_root: pathlib.Path,
) -> list[dict]:
    reason = _prepared_puffer_smoke_unavailability(puffer_root)
    if reason is not None:
        raise AssertionError(reason)
    runner = _runner()
    signature = inspect.signature(
        runner.run_prepared_one_update_smoke
    )
    if tuple(signature.parameters) != ("puffer_root",):
        raise AssertionError(
            "prepared smoke entry point must accept only puffer_root"
        )
    manifest = _protocol().load_protocol_manifest()
    receipts = []
    for _ in range(2):
        receipt = runner.run_prepared_one_update_smoke(
            str(puffer_root.resolve())
        )
        _validate_prepared_one_update_smoke_receipt(
            receipt,
            manifest=manifest,
            puffer_root=puffer_root,
        )
        receipts.append(receipt)
    if receipts[0] != receipts[1]:
        raise AssertionError(
            "duplicate prepared one-update smoke receipts differ"
        )
    return receipts


