    def test_masked_uniform_comparator_uses_stable_log1p_expm1_formula(
        self,
    ) -> None:
        comparator = self.manifest["budget"]["masked_uniform"]
        numerator = comparator["numerator"]
        denominator = comparator["denominator"]
        episodes = self.manifest["budget"]["episodes"]
        probability = numerator / denominator
        minimum = math.ceil(math.log(0.05) / math.log1p(-probability))
        at_budget = -math.expm1(episodes * math.log1p(-probability))
        self.assertEqual(minimum, 6052775)
        self.assertEqual(comparator["minimum_episodes_95"], minimum)
        self.assertEqual(round(at_budget, 10), 0.9500275582)
        self.assertEqual(
            comparator["probability_at_budget_rounded_10"],
            0.9500275582,
        )
        self.assertEqual(
            self.protocol.masked_uniform_comparator(
                numerator,
                denominator,
                episodes,
            ),
            {
                "minimum_episodes_95": 6052775,
                "probability_at_budget_rounded_10": 0.9500275582,
            },
        )

    def test_effective_config_binds_arguments_environment_and_protocol(
        self,
    ) -> None:
        environment_path = ROOT / "training/f5_trainability_env.json"
        environment_bytes = environment_path.read_bytes()
        environment = json.loads(environment_bytes)
        protocol_sha256 = hashlib.sha256(
            self.protocol.canonical_json_bytes(self.manifest)
        ).hexdigest()
        effective = {
            "arguments": copy.deepcopy(
                self.manifest["puffer"]["arguments"]
            ),
            "environment": {
                "mapping": environment,
                "path": "training/f5_trainability_env.json",
                "sha256": hashlib.sha256(environment_bytes).hexdigest(),
            },
            "protocol_sha256": protocol_sha256,
            "schema": "bloodbowl-f5-effective-config-v1",
        }
        self.protocol.validate_effective_config(
            effective,
            self.manifest,
        )
        mutations = []
        extra_argument = copy.deepcopy(effective)
        extra_argument["arguments"]["render"] = False
        mutations.append(extra_argument)
        changed_environment = copy.deepcopy(effective)
        changed_environment["environment"]["mapping"]["seed"] = 2
        mutations.append(changed_environment)
        changed_digest = copy.deepcopy(effective)
        changed_digest["environment"]["sha256"] = "0" * 64
        mutations.append(changed_digest)
        extra_root = copy.deepcopy(effective)
        extra_root["extension"] = None
        mutations.append(extra_root)
        for mutation in mutations:
            with self.subTest(keys=tuple(sorted(mutation))):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_effective_config(
                        mutation,
                        self.manifest,
                    )

