    def test_rng_state_digests_match_independent_literal_vectors(self) -> None:
        python_state = (3, tuple([0] * 624 + [624]), None)
        numpy_state = ("MT19937", tuple([0] * 624), 624, 0, 0.0)
        torch_state = bytes(5056)
        self.assertEqual(
            self.protocol.python_rng_sha256(python_state),
            "65918343143ac8d1b8c708a1c705efd2431c29e7b56ee5f33c1df29d36d0182b",
        )
        self.assertEqual(
            self.protocol.numpy_rng_sha256(numpy_state),
            "bc7557b8a4e8458765492ffa4e0d9c3517e303d317491c58ef7550ad9926bbe8",
        )
        self.assertEqual(
            self.protocol.torch_rng_sha256(torch_state),
            "2242b0ac30660da076a50b062f42c88e3378b0793aeda276b15d3b4398ffcd5c",
        )
        invalid_python = [
            (2, python_state[1], None),
            (3, tuple([0] * 624), None),
            (3, tuple([0] * 624 + [625]), None),
            (3, tuple([0] * 624 + [624]), math.nan),
        ]
        for state in invalid_python:
            with self.subTest(state_type="python"):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.python_rng_sha256(state)
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.numpy_rng_sha256(
                ("PCG64", tuple([0] * 624), 624, 0, 0.0)
            )
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.torch_rng_sha256(bytes(5055))

    def test_canonical_tensor_digest_uses_exact_binary_framing(self) -> None:
        items = [
            {
                "name": "a",
                "shape": (1,),
                "payload": struct.pack("<f", 1.0),
            },
            {
                "name": "z",
                "shape": (2, 1),
                "payload": struct.pack("<ff", -2.0, 0.5),
            },
        ]
        self.assertEqual(
            self.protocol.canonical_tensor_sha256(items),
            "5b61ec62ffbb281c3acf5d076a1f5919f30fd41457420731e2c18d73ce6b6c1a",
        )
        for invalid in (
            list(reversed(items)),
            [{**items[0], "payload": items[0]["payload"] + b"\x00"}],
            [{**items[0], "name": ""}],
            [{**items[0], "shape": (2,)}],
        ):
            with self.subTest(invalid=invalid):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.canonical_tensor_sha256(invalid)

    def test_little_bit_order_round_trip_and_padding_rejection(self) -> None:
        bits = [1, 0, 1, 1, 0, 0, 0, 1, 1, 0]
        packed = self.protocol.pack_success_bits(bits)
        self.assertEqual(packed, b"\x8d\x01")
        self.assertEqual(
            self.protocol.unpack_success_bits(packed, count=len(bits)),
            bits,
        )
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.unpack_success_bits(b"\x81", count=1)
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.pack_success_bits([0, 1, 2])

    def test_bitset_semantic_digest_binds_all_dimensions(self) -> None:
        raw = b"\x05"
        expected = hashlib.sha256(
            b"f5-success-bitset-v1\0"
            + struct.pack(">I", 512)
            + struct.pack(">I", 3)
            + struct.pack(">I", 1428436532)
            + struct.pack(">Q", 3)
            + b"\x00"
            + raw
        ).hexdigest()
        arguments = {
            "checkpoint_update": 512,
            "seed_index": 3,
            "action_seed": 1428436532,
            "episode_count": 3,
            "repeat_flag": 0,
            "raw": raw,
        }
        self.assertEqual(
            self.protocol.success_bitset_sha256(**arguments),
            expected,
        )
        for key, value in (
            ("checkpoint_update", 513),
            ("seed_index", 4),
            ("action_seed", 1428436533),
            ("episode_count", 4),
            ("repeat_flag", 1),
            ("raw", b"\x04"),
        ):
            mutated = dict(arguments)
            mutated[key] = value
            with self.subTest(key=key):
                self.assertNotEqual(
                    self.protocol.success_bitset_sha256(**mutated),
                    expected,
                )
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.success_bitset_sha256(
                **{**arguments, "repeat_flag": 2}
            )

    def test_wilson_interval_uses_the_frozen_binary64_order(self) -> None:
        interval = self.protocol.wilson95(0, 32768)
        self.assertEqual(interval, [0.0, 0.00011721827793903778])
        self.assertEqual(
            self.protocol.canonical_json_bytes(interval),
            b"[0.0,0.00011721827793903778]\n",
        )
        for successes, episodes in ((-1, 1), (2, 1), (0, 0), (True, 1)):
            with self.subTest(successes=successes, episodes=episodes):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.wilson95(successes, episodes)

    def test_parameter_l2_uses_exact_binary64_left_to_right_order(
        self,
    ) -> None:
        values = [
            struct.unpack("<f", struct.pack("<I", bits))[0]
            for bits in (0x3E50C49F, 0x414898A1, 0xB62BC82C)
        ]
        current = {
            "a": [values[0]],
            "b": [values[1]],
            "c": [values[2]],
        }
        initial = {
            "a": [struct.unpack("<f", struct.pack("<I", 0x3DCCCCCD))[0]],
            "b": [struct.unpack("<f", struct.pack("<I", 0x3F800000))[0]],
            "c": [struct.unpack("<f", struct.pack("<I", 0x00000000))[0]],
        }
        expected = _test_owned_parameter_l2(current, initial)
        observed = self.protocol.compute_parameter_l2(current, initial)
        self.assertEqual(
            struct.pack(">d", observed["norm"]).hex(),
            struct.pack(">d", expected["norm"]).hex(),
        )
        self.assertEqual(
            struct.pack(">d", observed["drift_from_initial"]).hex(),
            struct.pack(">d", expected["drift_from_initial"]).hex(),
        )
        self.assertNotEqual(
            observed["norm"],
            math.sqrt(math.fsum(value * value for value in values)),
            "math.fsum is not the frozen accumulation order",
        )

        reversed_mapping = {
            name: current[name] for name in reversed(tuple(current))
        }
        reversed_initial = {
            name: initial[name] for name in reversed(tuple(initial))
        }
        self.assertEqual(
            self.protocol.compute_parameter_l2(
                reversed_mapping,
                reversed_initial,
            ),
            observed,
            "mapping insertion order must not replace UTF-8 name order",
        )
        changed_c_order = copy.deepcopy(current)
        changed_initial_order = copy.deepcopy(initial)
        changed_c_order["a"] = [values[0], values[2]]
        changed_c_order.pop("c")
        changed_initial_order["a"] = [
            initial["a"][0],
            initial["c"][0],
        ]
        changed_initial_order.pop("c")
        reordered = self.protocol.compute_parameter_l2(
            changed_c_order,
            changed_initial_order,
        )
        self.assertNotEqual(
            struct.pack(">d", reordered["norm"]),
            struct.pack(">d", observed["norm"]),
            "within-tensor C-order is part of the binary64 result",
        )

