    def test_live_integrity_map_is_closed_and_rejects_error_empty_autoreset(
        self,
    ) -> None:
        fixtures = []
        error = _FakeCollector(mode="training")
        error.env_logs["error_episodes"] = 1 / 2048
        fixtures.append(("error", error))
        empty_legal = _FakeCollector(mode="training")
