    def test_real_prepared_seven_case_early_terminal_transaction(self) -> None:
        selected = os.environ.get("F5_PREPARED_PUFFER_ROOT")
        puffer_root = (
            pathlib.Path(selected)
            if selected is not None
            else DEFAULT_PREPARED_PUFFER_ROOT
        )
        unavailable = _prepared_puffer_smoke_unavailability(puffer_root)
        if unavailable is not None:
            if _exact_final_consumer_unavailability() is None:
                self.fail(
                    "mandatory exact-host early-terminal smoke is "
                    "unavailable: " + unavailable
                )
            self.skipTest(unavailable)
        runner = _runner()
        helper = runner.run_prepared_early_terminal_abort_smoke
        signature = inspect.signature(helper)
        self.assertEqual(
            tuple(signature.parameters),
            ("puffer_root", "snapshotter"),
        )
        self.assertEqual(
            signature.parameters["snapshotter"].kind,
            inspect.Parameter.KEYWORD_ONLY,
        )
        started = time.monotonic()
        receipt = helper(
            str(puffer_root.resolve()),
            snapshotter=_test_owned_muon_snapshot,
        )
        self.assertLess(time.monotonic() - started, 90)
        self.assertEqual(
            set(receipt),
            {"cases", "schema", "snapshot_mutations"},
        )
        self.assertEqual(
            receipt["schema"],
            "bloodbowl-f5-early-terminal-abort-smoke-v1",
        )
        cases = receipt["cases"]
        self.assertEqual(len(cases), 7)
        self.assertEqual(
            [case["delayed_row"] for case in cases],
            list(range(1, 8)),
        )

        expected_rows = bytearray(512)
        expected_rows[0] = 0b00000011
        expected_rollout_bitset = bytes(expected_rows).hex()
        snapshots = []
        for delayed_row, case in zip(range(1, 8), cases, strict=True):
            with self.subTest(delayed_row=delayed_row):
                self.assertEqual(
                    set(case),
                    {
                        "after",
                        "before",
                        "delayed_row",
                        "discarded",
                        "failure",
                        "injected_agent_rows",
                        "same_session_reuse_rejected_before_rollout",
                        "supervisor",
                        "tripwire_calls",
                    },
                )
                self.assertEqual(case["injected_agent_rows"], [0, 1])
                before = case["before"]
                after = case["after"]
                expected_snapshot_keys = {
                    "accepted_global_agent_step",
                    "accepted_ledger_jsonl",
                    "checkpoint_directory_snapshot",
                    "checkpoint_serialization_input",
                    "committed_epoch",
                    "model_raw_f5w",
                    "muon_snapshot",
                    "volatile_global_agent_step",
                }
                self.assertEqual(set(before), expected_snapshot_keys)
                self.assertEqual(set(after), expected_snapshot_keys)
                immutable_snapshot_keys = (
                    expected_snapshot_keys
                    - {"volatile_global_agent_step"}
                )
                for immutable_key in sorted(immutable_snapshot_keys):
                    self.assertEqual(
                        after[immutable_key],
                        before[immutable_key],
                        "rejected rollout mutated " + immutable_key,
                    )
                self.assertIs(
                    type(before["checkpoint_directory_snapshot"]),
                    bytes,
                )
                self.assertTrue(before["checkpoint_directory_snapshot"])
                self.assertEqual(
                    hashlib.sha256(before["model_raw_f5w"]).hexdigest(),
                    EXPECTED_ONE_UPDATE_RAW_SHA256,
                )
                self.assertEqual(
                    _canonical_tensor_sha256_from_raw_fixture(
                        before["model_raw_f5w"]
                    ),
                    EXPECTED_ONE_UPDATE_PARAMETER_SHA256,
                )
                self.assertEqual(before["committed_epoch"], 1)
                self.assertEqual(after["committed_epoch"], 1)
                self.assertEqual(
                    before["accepted_global_agent_step"],
                    32768,
                )
                self.assertEqual(
                    after["accepted_global_agent_step"],
                    32768,
                )
                self.assertEqual(
                    before["volatile_global_agent_step"],
                    32768,
                )
                self.assertEqual(
                    after["volatile_global_agent_step"],
                    65536,
                )
                self.assertEqual(
                    before["accepted_ledger_jsonl"].count(b"\n"),
                    1,
                )
                self.assertTrue(
                    before["accepted_ledger_jsonl"].endswith(b"\n")
                )
                self.assertTrue(
                    before["muon_snapshot"].startswith(
                        b"bloodbowl-f5-muon-snapshot-v1\0"
                    )
                )
                snapshots.append(before["muon_snapshot"])
                self.assertEqual(
                    case["failure"],
                    {
                        "accepted_global_agent_step": 32768,
                        "attempted_update_index": 1,
                        "committed_epoch": 1,
                        "learner_disposition": "discarded",
                        "rollout": {
                            "agent_row_count": 2,
                            "agent_rows_bitset_hex": (
                                expected_rollout_bitset
                            ),
                            "check": "early-terminal",
                            "delayed_row": delayed_row,
                            "mode": "training",
                        },
                        "volatile_global_agent_step": 65536,
                    },
                )
                self.assertEqual(
                    case["tripwire_calls"],
                    {
                        "accepted_commit_dispatch": 0,
                        "fixed_checkpoint_schedule_dispatch": 0,
                        "optimizer_dispatch": 0,
                        "worker_success_frame_emission": 0,
                    },
                )
                self.assertTrue(case["discarded"])
                self.assertTrue(
                    case["same_session_reuse_rejected_before_rollout"]
                )
                self.assertEqual(
                    case["supervisor"],
                    {
                        "accepted_frames": ["worker-failure"],
                        "destination_topology_after": [],
                        "private_spool_topology_after": [],
                        "success_leaf_created": False,
                    },
                )
        self.assertTrue(all(snapshot == snapshots[0] for snapshot in snapshots))

        mutations = receipt["snapshot_mutations"]
        expected_mutation_families = {
            "default-eps",
            "default-lr",
            "default-momentum",
            "default-weight_decay",
            "group-eps",
            "group-lr",
            "group-momentum",
            "group-weight_decay",
            "group-parameter-order",
            "group-parameter-membership",
            "state-key-membership",
            "state-field",
            "tensor-name",
            "tensor-dtype",
            "tensor-shape",
            "tensor-stride",
            "tensor-storage-offset",
            "tensor-element-count",
            "tensor-byte-count",
            "tensor-requires-grad",
            "tensor-raw-sha256",
            "tensor-raw-bytes",
        }
        self.assertEqual(
            {record["family"] for record in mutations},
            expected_mutation_families,
        )
        self.assertTrue(
            all(
                set(record)
                == {"after_sha256", "before_sha256", "family"}
                and record["after_sha256"] != record["before_sha256"]
                for record in mutations
            )
        )

