    def _assert_worker_contract_evaluation(
        self,
        *,
        label,
        build_frames,
        expected_spool_payloads,
        postflight_expected,
    ) -> None:
        for module, population in self._supervisor_cases():
            fixture = _test_evaluation_worker_stream(population)
            frames = tuple(build_frames(fixture))
            self.assertEqual(len(frames), 2)
            self.assertTrue(
                all(
                    type(frame["wire"]) is bytes
                    and len(frame["wire"]) <= 65536
                    for frame in frames
                )
            )
            operations = _PreparedWorkerSupervisorDouble(
                fixture,
                stdout_chunks=[
                    frames[0]["wire"],
                    frames[1]["wire"],
                    _PIPE_EOF,
                ],
                stderr_chunks=[_PIPE_EOF],
                child_states=[("exit", 0)],
            )
            try:
                with self.subTest(owner=module.__name__, mutation=label):
                    failure = self._invoke_failure(
                        module,
                        operations,
                        fixture,
                    )
                    self.assertEqual(failure["status"], "integrity-abort")
                    self.assertEqual(failure["cause"], "worker-contract")
                    self.assertEqual(
                        failure["phase"],
                        (
                            "controller-evaluation-worker"
                            if population == "controller"
                            else "verifier-evaluation-worker"
                        ),
                    )
                    self.assertEqual(
                        failure["worker_job_sha256"],
                        _test_worker_job_sha256(fixture["job"]),
                    )
                    self.assertEqual(operations.signals, [])
                    with self.assertRaises(AssertionError):
                        _test_supervised_result_record(failure)
                    self.assertEqual(
                        [bytes(spool.raw) for spool in operations.spools],
                        list(expected_spool_payloads(fixture, frames)),
                    )
                    self.assertTrue(
                        all(spool.closed for spool in operations.spools)
                    )
                    terminal = next(
                        index
                        for index, event in enumerate(operations.events)
                        if event[0] == "child_status"
                        and event[1] == ("exit", 0)
                    )
                    first_read = next(
                        index
                        for index, event in enumerate(operations.events)
                        if event[0] == "read_result"
                    )
                    self.assertLess(terminal, first_read)
                    stdout_eof = max(
                        index
                        for index, event in enumerate(operations.events)
                        if event == ("read_result", "stdout", 0)
                    )
                    stderr_eof = max(
                        index
                        for index, event in enumerate(operations.events)
                        if event == ("read_result", "stderr", 0)
                    )
                    terminal_barrier = max(
                        index
                        for index, event in enumerate(operations.events)
                        if (
                            event[0] == "child_status"
                            and event[1] == ("exit", 0)
                        )
                        or (
                            event[0] == "reap_result"
                            and event[1] == ("exit", 0)
                        )
                    )
                    if postflight_expected:
                        self.assertEqual(
                            operations.postflight_jobs,
                            [fixture["job"]],
                        )
                        postflights = [
                            index
                            for index, event in enumerate(operations.events)
                            if event[0] == "run_outer_worker_postflight"
                        ]
                        self.assertEqual(len(postflights), 1)
                        self.assertGreater(
                            postflights[0],
                            max(stdout_eof, stderr_eof, terminal_barrier),
                        )
                    else:
                        self.assertEqual(operations.postflight_jobs, [])
                        self.assertFalse(
                            any(
                                event[0] == "run_outer_worker_postflight"
                                for event in operations.events
                            )
                        )
                    self.assertEqual(
                        bytes(operations.input_bytes),
                        fixture["job_wire"],
                    )
                    self.assertTrue(operations.input_closed)
                    self.assertEqual(len(operations.stdout_chunks), 0)
                    self.assertEqual(len(operations.stderr_chunks), 0)
                    self._assert_failure_cleanup(operations)
            finally:
                operations.cleanup()

    def _assert_worker_contract_training(
        self,
        *,
        label,
        build_frames,
        expected_spool_indices,
        postflight_expected,
        virtual_unchanged_prefix=False,
    ) -> None:
        fixture = self.training_fixture
        source_headers = copy.deepcopy(fixture["headers"])
        source_record = copy.deepcopy(fixture["record"])
        frames = tuple(build_frames(fixture))
        self.assertEqual(len(frames), 8)
        self.assertEqual(fixture["headers"], source_headers)
        self.assertEqual(fixture["record"], source_record)
        expected_spool_indices = tuple(expected_spool_indices)
        self.assertEqual(
            expected_spool_indices,
            tuple(range(len(expected_spool_indices))),
        )
        self.assertTrue(
            all(
                type(frame["wire"]) is bytes
                and type(frame["payload"]) is bytes
                for frame in frames
            )
        )
        per_frame_chunks = []
        for frame_index, frame in enumerate(frames):
            if frame is fixture["frames"][frame_index]:
                chunks = self.training_frame_wire_chunks[frame_index]
            else:
                chunks = tuple(
                    frame["wire"][offset : offset + 65536]
                    for offset in range(0, len(frame["wire"]), 65536)
                )
                self.assertEqual(b"".join(chunks), frame["wire"])
            self.assertTrue(chunks)
            self.assertTrue(
                all(0 < len(chunk) <= 65536 for chunk in chunks)
            )
            self.assertEqual(
                sum(len(chunk) for chunk in chunks),
                len(frame["wire"]),
            )
            per_frame_chunks.append(chunks)
        stdout_chunks = tuple(
            chunk for chunks in per_frame_chunks for chunk in chunks
        )
        self.assertEqual(len(per_frame_chunks), 8)
        self.assertEqual(
            sum(len(chunk) for chunk in stdout_chunks),
            sum(len(frame["wire"]) for frame in frames),
        )
        if virtual_unchanged_prefix:
            self.assertEqual(expected_spool_indices, tuple(range(8)))
            self.assertTrue(
                all(
                    frames[index] is fixture["frames"][index]
                    for index in range(7)
                )
            )
            operations = _ExpectedPayloadVirtualSpoolSupervisorDouble(
                fixture,
                stdout_chunks=[*stdout_chunks, _PIPE_EOF],
                stderr_chunks=[_PIPE_EOF],
                child_states=[("exit", 0)],
                runtime_scratch=self.training_runtime_scratch,
            )
        else:
            operations = _PreparedWorkerSupervisorDouble(
                fixture,
                stdout_chunks=[*stdout_chunks, _PIPE_EOF],
                stderr_chunks=[_PIPE_EOF],
                child_states=[("exit", 0)],
                runtime_scratch=self.training_runtime_scratch,
            )
        try:
            with self.subTest(owner="runner", mutation=label):
                failure = self._invoke_failure(
                    _runner(),
                    operations,
                    fixture,
                )
                self.assertEqual(failure["status"], "integrity-abort")
                self.assertEqual(failure["cause"], "worker-contract")
                self.assertEqual(failure["phase"], "training-worker")
                self.assertEqual(
                    failure["worker_job_sha256"],
                    _test_worker_job_sha256(fixture["job"]),
                )
                with self.assertRaises(AssertionError):
                    _test_supervised_result_record(failure)
                self.assertEqual(operations.signals, [])
                self.assertEqual(
                    bytes(operations.input_bytes),
                    fixture["job_wire"],
                )
                self.assertTrue(operations.input_closed)
                self.assertEqual(len(operations.stdout_chunks), 0)
                self.assertEqual(len(operations.stderr_chunks), 0)
                self.assertEqual(
                    collections.Counter(
                        (role, size)
                        for role, size, _when in operations.read_observations
                        if size == 0
                    ),
                    collections.Counter(
                        {("stdout", 0): 1, ("stderr", 0): 1}
                    ),
                )
                self.assertEqual(
                    sum(
                        size
                        for role, size, _when in operations.read_observations
                        if role == "stdout"
                        and type(size) is int
                        and size > 0
                    ),
                    sum(len(frame["wire"]) for frame in frames),
                )
                self.assertEqual(
                    sum(
                        size
                        for role, size, _when in operations.read_observations
                        if role == "stderr"
                        and type(size) is int
                        and size > 0
                    ),
                    0,
                )
                terminal = next(
                    index
                    for index, event in enumerate(operations.events)
                    if event[0] == "child_status"
                    and event[1] == ("exit", 0)
                )
                first_descriptor_read = next(
                    index
                    for index, event in enumerate(operations.events)
                    if event[0] == "read_nonblocking"
                )
                self.assertLess(terminal, first_descriptor_read)
                stdout_eof = next(
                    index
                    for index, event in enumerate(operations.events)
                    if event == ("read_result", "stdout", 0)
                )
                stderr_eof = next(
                    index
                    for index, event in enumerate(operations.events)
                    if event == ("read_result", "stderr", 0)
                )
                terminal_barrier = max(
                    index
                    for index, event in enumerate(operations.events)
                    if (
                        event[0] == "child_status"
                        and event[1] == ("exit", 0)
                    )
                    or (
                        event[0] == "reap_result"
                        and event[1] == ("exit", 0)
                    )
                )
                if postflight_expected:
                    self.assertEqual(
                        operations.postflight_jobs,
                        [fixture["job"]],
                    )
                    postflights = [
                        index
                        for index, event in enumerate(operations.events)
                        if event[0] == "run_outer_worker_postflight"
                    ]
                    self.assertEqual(len(postflights), 1)
                    self.assertGreater(
                        postflights[0],
                        max(stdout_eof, stderr_eof, terminal_barrier),
                    )
                else:
                    self.assertEqual(operations.postflight_jobs, [])
                    self.assertFalse(
                        any(
                            event[0] == "run_outer_worker_postflight"
                            for event in operations.events
                        )
                    )
                self.assertEqual(
                    len(operations.spools),
                    len(expected_spool_indices),
                )
                expected_identities = [
                    (
                        frames[index]["header"]["frame_index"],
                        frames[index]["header"]["kind"],
                        frames[index]["header"]["logical_name"],
                    )
                    for index in expected_spool_indices
                ]
                self.assertEqual(
                    [spool.identity for spool in operations.spools],
                    expected_identities,
                )
                if virtual_unchanged_prefix:
                    virtual_spools = operations.spools[:7]
                    self.assertTrue(
                        all(
                            isinstance(
                                spool,
                                _ExpectedPayloadVirtualSpool,
                            )
                            for spool in virtual_spools
                        )
                    )
                    self.assertIsInstance(
                        operations.spools[7],
                        _PreparedWorkerSpool,
                    )
                    for index, spool in enumerate(virtual_spools):
                        expected_payload = fixture["payloads"][index]
                        self.assertIs(spool.expected_payload, expected_payload)
                        self.assertEqual(
                            spool.write_offset,
                            len(expected_payload),
                        )
                        self.assertEqual(
                            sum(spool.write_chunk_sizes),
                            len(expected_payload),
                        )
                        self.assertTrue(spool.write_chunk_sizes)
                        self.assertTrue(
                            all(
                                0 < size <= 65536
                                for size in spool.write_chunk_sizes
                            )
                        )
                        self.assertTrue(spool.read_passes)
                        self.assertTrue(
                            all(
                                read_pass["bytes"]
                                == len(expected_payload)
                                and sum(read_pass["chunks"])
                                == len(expected_payload)
                                and all(
                                    0 < size <= 65536
                                    for size in read_pass["chunks"]
                                )
                                for read_pass in spool.read_passes
                            )
                        )
                        self.assertEqual(spool.close_count, 1)
                    self.assertEqual(
                        bytes(operations.spools[7].raw),
                        frames[7]["payload"],
                    )
                    self.assertEqual(
                        operations.created_spool_identities,
                        set(expected_identities),
                    )
                else:
                    self.assertTrue(
                        all(
                            isinstance(spool, _PreparedWorkerSpool)
                            for spool in operations.spools
                        )
                    )
                    self.assertEqual(
                        [bytes(spool.raw) for spool in operations.spools],
                        [frames[index]["payload"] for index in expected_spool_indices],
                    )
                self.assertTrue(all(spool.closed for spool in operations.spools))
                spool_closes = collections.Counter(
                    event[1]
                    for event in operations.events
                    if event[0] == "close_private_spool"
                )
                self.assertEqual(
                    spool_closes,
                    collections.Counter(
                        {identity: 1 for identity in expected_identities}
                    ),
                )
                self.assertTrue(
                    all(
                        0 < size <= 65536
                        for _identity, size in operations.spool_writes
                    )
                )
                self.assertTrue(
                    all(
                        type(event[2]) is int and 1 <= event[2] <= 65536
                        for event in operations.events
                        if event[0] == "read_private_spool"
                    )
                )
                self._assert_exact_spawn_and_scratch(
                    _runner(),
                    operations,
                    fixture,
                )
                self._assert_failure_cleanup(operations)
        finally:
            operations.cleanup()

