    def test_training_streamed_semantic_header_matrix(
        self,
    ) -> None:
        cases = tuple(
            (frame_index, f"frame-{frame_index}-semantic-only")
            for frame_index in range(8)
        )
        self.assertEqual(len(cases), 8)
        self.assertEqual(
            {frame_index for frame_index, _label in cases},
            set(range(8)),
        )
        self.assertEqual(len({label for _index, label in cases}), 8)
        for frame_index, label in cases:
            def build(fixture, selected=frame_index):
                original = fixture["frames"][selected]
                replacement = (
                    "0" * 64
                    if original["header"]["semantic_sha256"] != "0" * 64
                    else "1" * 64
                )
                changed = _test_replace_only_frame_semantic_sha256(
                    original,
                    replacement,
                )
                self.assertEqual(
                    changed["payload"],
                    original["payload"],
                )
                self.assertEqual(
                    changed["header"]["raw_sha256"],
                    original["header"]["raw_sha256"],
                )
                self.assertEqual(
                    {
                        key: value
                        for key, value in changed["header"].items()
                        if key != "semantic_sha256"
                    },
                    {
                        key: value
                        for key, value in original["header"].items()
                        if key != "semantic_sha256"
                    },
                )
                frames = list(fixture["frames"])
                frames[selected] = changed
                return tuple(frames)

            self._assert_worker_contract_training(
                label=label,
                build_frames=build,
                expected_spool_indices=range(frame_index + 1),
                postflight_expected=False,
            )

    def test_training_trace_content_semantic_matrix(
        self,
    ) -> None:
        labels = (
            "invalid-utf8",
            "identical-duplicate-root-key",
            "row-100-update-index-100-to-101",
        )
        self.assertEqual(len(labels), 3)
        self.assertEqual(
            set(labels),
            {
                "invalid-utf8",
                "identical-duplicate-root-key",
                "row-100-update-index-100-to-101",
            },
        )

        def mutated_trace(label, fixture):
            original = fixture["frames"][0]["payload"]
            self.assertEqual(original.count(b"\n"), 2956)
            self.assertTrue(original.endswith(b"\n"))
            if label == "invalid-utf8":
                raw = b"\xff" + original[1:]
                with self.assertRaises(UnicodeDecodeError):
                    raw.decode("utf-8")
            elif label == "identical-duplicate-root-key":
                lines = original.splitlines(keepends=True)
                self.assertEqual(len(lines), 2956)
                selected = 100
                before = json.loads(lines[selected])
                key = sorted(before)[0]
                singleton = _canonical_json_fixture({key: before[key]})
                duplicate_leaf = singleton[1:-2]
                changed_line = (
                    b"{" + duplicate_leaf + b"," + lines[selected][1:]
                )
                self.assertEqual(json.loads(changed_line), before)
                self.assertEqual(
                    changed_line.count(json.dumps(key).encode("ascii")),
                    lines[selected].count(json.dumps(key).encode("ascii"))
                    + 1,
                )
                lines[selected] = changed_line
                raw = b"".join(lines)
            elif label == "row-100-update-index-100-to-101":
                rows = [json.loads(line) for line in original.splitlines()]
                self.assertEqual(len(rows), 2956)
                self.assertEqual(rows[100]["update_index"], 100)
                rows[100]["update_index"] = 101
                raw = b"".join(
                    _canonical_json_fixture(row) for row in rows
                )
                self.assertEqual(
                    raw,
                    b"".join(
                        _canonical_json_fixture(json.loads(line))
                        for line in raw.splitlines()
                    ),
                )
            else:
                raise AssertionError("unowned training trace mutation")
            self.assertNotEqual(raw, original)
            self.assertEqual(raw.count(b"\n"), 2956)
            self.assertTrue(raw.endswith(b"\n"))
            return raw

        for label in labels:
            def build(fixture, selected=label):
                raw = mutated_trace(selected, fixture)
                changed = _test_rebuild_training_semantic_frame(
                    fixture["frames"][0],
                    raw,
                    semantic_sha256=hashlib.sha256(
                        b"f5-training-trace-v1\0" + raw
                    ).hexdigest(),
                )
                return (changed, *fixture["frames"][1:])

            self._assert_worker_contract_training(
                label=label,
                build_frames=build,
                expected_spool_indices=(0,),
                postflight_expected=False,
            )

    def test_training_checkpoint_zero_qnan_semantic_rejection(
        self,
    ) -> None:
        def build(fixture):
            original = fixture["frames"][1]
            original_raw = original["payload"]
            self.assertEqual(len(original_raw), 879900)
            self.assertNotEqual(original_raw[:4], b"\x00\x00\xc0\x7f")
            self.assertEqual(
                _test_canonical_tensor_sha256_from_raw_slices(original_raw),
                original["header"]["semantic_sha256"],
            )
            changed_raw = bytearray(original_raw)
            changed_raw[:4] = b"\x00\x00\xc0\x7f"
            changed_raw = bytes(changed_raw)
            self.assertEqual(changed_raw[:4], b"\x00\x00\xc0\x7f")
            self.assertEqual(len(changed_raw), len(original_raw))
            self.assertNotEqual(
                hashlib.sha256(changed_raw).hexdigest(),
                original["header"]["raw_sha256"],
            )
            semantic_sha256 = (
                _test_canonical_tensor_sha256_from_raw_slices(changed_raw)
            )
            self.assertNotEqual(
                semantic_sha256,
                original["header"]["semantic_sha256"],
            )
            changed = _test_rebuild_training_semantic_frame(
                original,
                changed_raw,
                semantic_sha256=semantic_sha256,
            )
            frames = list(fixture["frames"])
            frames[1] = changed
            return tuple(frames)

        self._assert_worker_contract_training(
            label="checkpoint-0-first-float-qnan",
            build_frames=build,
            expected_spool_indices=(0, 1),
            postflight_expected=False,
        )

    def test_training_typed_result_and_binding_negative_matrix(
        self,
    ) -> None:
        raw_labels = (
            "invalid-utf8",
            "malformed-json",
            "full-whitespace-json",
            "full-identical-duplicate-key-json",
            "canonical-scalar",
            "canonical-list",
            "canonical-null",
        )
        self.assertEqual(len(raw_labels), 7)
        self.assertEqual(
            set(raw_labels),
            {
                "invalid-utf8",
                "malformed-json",
                "full-whitespace-json",
                "full-identical-duplicate-key-json",
                "canonical-scalar",
                "canonical-list",
                "canonical-null",
            },
        )

        def raw_result_payload(label, fixture):
            record = fixture["record"]
            canonical = fixture["frames"][7]["payload"]
            self.assertEqual(
                tuple(sorted(record)),
                TRAINING_WORKER_RESULT_FIELDS,
            )
            if label == "invalid-utf8":
                return b"\xff\n"
            if label == "malformed-json":
                return b"{\n"
            if label == "full-whitespace-json":
                raw = (
                    json.dumps(
                        record,
                        allow_nan=False,
                        ensure_ascii=True,
                        sort_keys=True,
                    ).encode("ascii")
                    + b"\n"
                )
                self.assertEqual(json.loads(raw), record)
                self.assertNotEqual(raw, canonical)
                return raw
            if label == "full-identical-duplicate-key-json":
                key = sorted(record)[0]
                singleton = _canonical_json_fixture({key: record[key]})
                duplicate_leaf = singleton[1:-2]
                raw = b"{" + duplicate_leaf + b"," + canonical[1:]
                encoded_key = json.dumps(key).encode("ascii")
                self.assertEqual(
                    raw.count(encoded_key),
                    canonical.count(encoded_key) + 1,
                )
                self.assertEqual(json.loads(raw), record)
                self.assertNotEqual(raw, canonical)
                return raw
            if label == "canonical-scalar":
                return b"1\n"
            if label == "canonical-list":
                return b"[]\n"
            if label == "canonical-null":
                return b"null\n"
            raise AssertionError("unowned raw training-result case")

        specifications = [
            ("D", label, "raw", label, (), ()) for label in raw_labels
        ]
        specifications.extend(
            (
                "E",
                "remove-" + field,
                "typed",
                {},
                ((field,),),
                {},
            )
            for field in TRAINING_WORKER_RESULT_FIELDS
        )
        specifications.append(
            ("E", "extra-field", "typed", {}, (), {("extension",): None})
        )
        alternate_digest = "0" * 64
        alternate_nonce = "0" * 32
        specifications.extend(
            (
                "F",
                label,
                "typed",
                replacements,
                (),
                {},
            )
            for label, replacements in (
                (
                    "initial-parameter-valid-alternate",
                    {("initial_parameter_sha256",): alternate_digest},
                ),
                (
                    "initial-reconstruction-valid-alternate",
                    {("initial_reconstruction_sha256",): alternate_digest},
                ),
                (
                    "job-sha-valid-alternate",
                    {("job_sha256",): alternate_digest},
                ),
                (
                    "nonce-valid-alternate",
                    {("nonce",): alternate_nonce},
                ),
                (
                    "schema-wrong-literal",
                    {
                        ("schema",): (
                            "bloodbowl-f5-training-worker-result-v2"
                        )
                    },
                ),
                (
                    "worker-kind-evaluation",
                    {("worker_kind",): "evaluation"},
                ),
            )
        )
        for field in (
            "audit",
            "effective_config",
            "rng",
            "startup",
            "trace_frame",
            "training",
        ):
            specifications.append(
                (
                    "G",
                    field.replace("_", "-") + "-wrong-container",
                    "typed",
                    {(field,): []},
                    (),
                    {},
                )
            )
        specifications.append(
            (
                "G",
                "checkpoint-frames-wrong-container",
                "typed",
                {("checkpoint_frames",): {}},
                (),
                {},
            )
        )

        def checkpoint_topology(fixture, mode):
            bindings = copy.deepcopy(fixture["record"]["checkpoint_frames"])
            self.assertEqual(len(bindings), 6)
            if mode == "five":
                return {("checkpoint_frames",): bindings[:5]}
            if mode == "seven":
                return {("checkpoint_frames",): [*bindings, bindings[-1]]}
            if mode == "reversed":
                return {("checkpoint_frames",): list(reversed(bindings))}
            if mode == "element-zero-list":
                return {("checkpoint_frames", 0): []}
            raise AssertionError("unowned checkpoint topology case")

        for label, mode in (
            ("checkpoint-frames-five", "five"),
            ("checkpoint-frames-seven", "seven"),
            ("checkpoint-frames-reversed", "reversed"),
            ("checkpoint-frame-zero-wrong-container", "element-zero-list"),
        ):
            specifications.append(
                (
                    "H",
                    label,
                    "typed-dynamic",
                    (
                        lambda fixture, selected=mode: checkpoint_topology(
                            fixture,
                            selected,
                        )
                    ),
                    (),
                    {},
                )
            )

        binding_targets = [("trace-frame", ("trace_frame",))]
        binding_targets.extend(
            (
                f"checkpoint-frame-{index}",
                ("checkpoint_frames", index),
            )
            for index in range(6)
        )
        self.assertEqual(len(binding_targets), 7)
        self.assertEqual(
            {path for _label, path in binding_targets},
            {
                ("trace_frame",),
                *(("checkpoint_frames", index) for index in range(6)),
            },
        )

        def value_at_path(root, path):
            value = root
            for component in path:
                value = value[component]
            return value

        def observed_binding_replacement(fixture, path, field):
            original = value_at_path(fixture["record"], (*path, field))
            if field == "bytes":
                replacement = original + 1
                self.assertGreaterEqual(replacement, 0)
            elif field == "frame_index":
                replacement = (original + 1) % 7
                self.assertIn(replacement, range(7))
            elif field == "logical_name":
                replacement = original + ".alternate"
                replacement.encode("ascii")
            elif field in {"raw_sha256", "semantic_sha256"}:
                replacement = (
                    "0" * 64 if original != "0" * 64 else "1" * 64
                )
                self.assertRegex(replacement, r"^[0-9a-f]{64}$")
            else:
                raise AssertionError("unowned observed binding field")
            self.assertIs(type(replacement), type(original))
            self.assertIsNot(type(replacement), bool)
            self.assertNotEqual(original, replacement)
            return {(*path, field): replacement}

        for target_label, path in binding_targets:
            for field in WORKER_FRAME_BINDING_FIELDS:
                specifications.append(
                    (
                        "I",
                        f"{target_label}-observed-{field.replace('_', '-')}",
                        "typed-dynamic",
                        (
                            lambda fixture,
                            selected_path=path,
                            selected_field=field: (
                                observed_binding_replacement(
                                    fixture,
                                    selected_path,
                                    selected_field,
                                )
                            )
                        ),
                        (),
                        {},
                    )
                )

        strict_binding_mutations = [
            (
                "remove-" + field,
                {},
                (field,),
                {},
            )
            for field in WORKER_FRAME_BINDING_FIELDS
        ]
        strict_binding_mutations.extend(
            (
                ("extra-field", {}, (), {"extension": None}),
                ("bytes-bool", {"bytes": True}, (), {}),
                ("bytes-negative", {"bytes": -1}, (), {}),
                ("frame-index-bool", {"frame_index": False}, (), {}),
                ("frame-index-negative", {"frame_index": -1}, (), {}),
                ("logical-name-nonstring", {"logical_name": 7}, (), {}),
                (
                    "logical-name-nonascii",
                    {"logical_name": "\u00e9"},
                    (),
                    {},
                ),
                ("raw-sha-nonstring", {"raw_sha256": 7}, (), {}),
                (
                    "raw-sha-malformed",
                    {"raw_sha256": "g" * 64},
                    (),
                    {},
                ),
                (
                    "semantic-sha-nonstring",
                    {"semantic_sha256": 7},
                    (),
                    {},
                ),
                (
                    "semantic-sha-malformed",
                    {"semantic_sha256": "g" * 64},
                    (),
                    {},
                ),
            )
        )
        self.assertEqual(len(strict_binding_mutations), 16)
        for target_label, path in binding_targets[:2]:
            for label, replacements, removals, additions in (
                strict_binding_mutations
            ):
                specifications.append(
                    (
                        "J",
                        f"{target_label}-strict-{label}",
                        "typed",
                        {
                            (*path, field): value
                            for field, value in replacements.items()
                        },
                        tuple((*path, field) for field in removals),
                        {
                            (*path, field): value
                            for field, value in additions.items()
                        },
                    )
                )

        specifications.extend(
            (
                "K",
                label,
                "typed",
                replacements,
                (),
                {},
            )
            for label, replacements in (
                ("job-sha-nonstring", {("job_sha256",): 7}),
                ("job-sha-malformed", {("job_sha256",): "g" * 64}),
                ("nonce-nonstring", {("nonce",): 7}),
                ("nonce-malformed", {("nonce",): "g" * 32}),
                ("schema-nonstring", {("schema",): 7}),
                ("worker-kind-nonstring", {("worker_kind",): 7}),
            )
        )
        expected_labels = {
            "D": set(raw_labels),
            "E": {
                *("remove-" + field for field in TRAINING_WORKER_RESULT_FIELDS),
                "extra-field",
            },
            "F": {
                "initial-parameter-valid-alternate",
                "initial-reconstruction-valid-alternate",
                "job-sha-valid-alternate",
                "nonce-valid-alternate",
                "schema-wrong-literal",
                "worker-kind-evaluation",
            },
            "G": {
                "audit-wrong-container",
                "effective-config-wrong-container",
                "rng-wrong-container",
                "startup-wrong-container",
                "trace-frame-wrong-container",
                "training-wrong-container",
                "checkpoint-frames-wrong-container",
            },
            "H": {
                "checkpoint-frames-five",
                "checkpoint-frames-seven",
                "checkpoint-frames-reversed",
                "checkpoint-frame-zero-wrong-container",
            },
            "I": {
                f"{target}-observed-{field.replace('_', '-')}"
                for target, _path in binding_targets
                for field in WORKER_FRAME_BINDING_FIELDS
            },
            "J": {
                f"{target}-strict-{label}"
                for target, _path in binding_targets[:2]
                for label, _replacement, _removal, _addition in (
                    strict_binding_mutations
                )
            },
            "K": {
                "job-sha-nonstring",
                "job-sha-malformed",
                "nonce-nonstring",
                "nonce-malformed",
                "schema-nonstring",
                "worker-kind-nonstring",
            },
        }
        observed_labels = collections.defaultdict(set)
        for section, label, _kind, _value, _remove, _add in specifications:
            observed_labels[section].add(label)
        self.assertEqual(dict(observed_labels), expected_labels)
        self.assertEqual(
            {
                removals[0][0]
                for section, label, _kind, _value, removals, _add in (
                    specifications
                )
                if section == "E" and label.startswith("remove-")
            },
            set(TRAINING_WORKER_RESULT_FIELDS),
        )
        section_counts = collections.Counter(
            section for section, _label, _kind, _value, _remove, _add in specifications
        )
        self.assertEqual(
            section_counts,
            collections.Counter(
                {"D": 7, "E": 14, "F": 6, "G": 7, "H": 4,
                 "I": 35, "J": 32, "K": 6}
            ),
        )
        self.assertEqual(len(specifications), 111)
        qualified_labels = [
            f"{section}-{label}"
            for section, label, _kind, _value, _remove, _add in specifications
        ]
        self.assertEqual(len(set(qualified_labels)), 111)
        self.assertEqual(
            8 + 3 + 1 + len(specifications),
            123,
        )
        self.assertRegex(alternate_digest, r"^[0-9a-f]{64}$")
        self.assertRegex(alternate_nonce, r"^[0-9a-f]{32}$")
        self.assertNotEqual(
            alternate_digest,
            EXPECTED_INITIAL_PARAMETER_SHA256,
        )
        for section, label, kind, value, removals, additions in specifications:
            def build(
                fixture,
                selected_kind=kind,
                selected_value=value,
                selected_removals=removals,
                selected_additions=additions,
            ):
                if selected_kind == "raw":
                    result_frame = _test_rebuild_result_frame_from_raw_payload(
                        fixture["frames"][7],
                        raw_result_payload(selected_value, fixture),
                    )
                elif selected_kind in {"typed", "typed-dynamic"}:
                    replacements = (
                        selected_value(fixture)
                        if selected_kind == "typed-dynamic"
                        else selected_value
                    )
                    _record, result_frame = (
                        _test_mutate_canonical_training_result(
                            fixture,
                            replacements=replacements,
                            removals=selected_removals,
                            additions=selected_additions,
                        )
                    )
                else:
                    raise AssertionError("unowned training-result builder")
                self.assertNotEqual(
                    result_frame["payload"],
                    fixture["frames"][7]["payload"],
                )
                return (*fixture["frames"][:7], result_frame)

            self._assert_worker_contract_training(
                label=f"{section}-{label}",
                build_frames=build,
                expected_spool_indices=range(8),
                postflight_expected=True,
                virtual_unchanged_prefix=True,
            )

