            self.assertEqual(set(replacements), {replacement_path})
            self.assertNotEqual(replacements[replacement_path], resolved[role])
            resulting_claims = dict(original_claims)
            resulting_claims[role] = child_claims[role]
            self.assertEqual(len(set(resulting_claims.values())), 4)
            return replacements

