        def isolated_sys_path_replacement(fixture, index):
            original = list(
                fixture["record"]["startup"]["worker_sys_path"]
            )
            self.assertEqual(len(original), 5)
            self.assertEqual(len(set(original)), 5)
            for existing in original:
                self.assertIs(type(existing), str)
                self.assertTrue(existing.isascii())
                self.assertTrue(existing.isprintable())
                self.assertTrue(os.path.isabs(existing))
                self.assertEqual(
                    os.path.normpath(existing),
                    existing,
                )
            puffer_root_value = fixture["job"]["puffer_root"]
            self.assertIs(type(puffer_root_value), str)
            self.assertTrue(puffer_root_value.isascii())
            self.assertTrue(puffer_root_value.isprintable())
            self.assertTrue(os.path.isabs(puffer_root_value))
            self.assertEqual(
                os.path.normpath(puffer_root_value),
                puffer_root_value,
            )
            manifest_sys_path = fixture["manifest"]["runtime"][
                "worker"
            ]["sys_path"]
            self.assertEqual(len(manifest_sys_path), 5)
            self.assertEqual(
                original,
                [
                    value.replace(
                        "<prepared-puffer-root>",
                        puffer_root_value,
                    )
                    for value in manifest_sys_path
                ],
            )

            original_paths = [pathlib.Path(value) for value in original]
            puffer_root = pathlib.Path(puffer_root_value)
            self.assertEqual(
                original_paths[0],
                original_paths[1].parent / "python312.zip",
            )
            self.assertEqual(
                original_paths[2],
                original_paths[1] / "lib-dynload",
            )
            self.assertEqual(
                original_paths[3],
                puffer_root
                / ".venv/lib/python3.12/site-packages",
            )
            self.assertEqual(original_paths[4], puffer_root)

            if index == 0:
                coarse_root = original_paths[1].parents[1]
                candidate = original_paths[1] / "encodings"
            elif index == 3:
                coarse_root = original_paths[3]
                candidate = coarse_root / "numpy"
            elif index == 4:
                coarse_root = puffer_root
                candidate = coarse_root / "pufferlib"
            else:
                raise AssertionError("unowned isolated sys.path index")

            coarse_root_value = str(coarse_root)
            candidate_value = str(candidate)
            self.assertTrue(coarse_root_value.isascii())
            self.assertTrue(coarse_root_value.isprintable())
            self.assertTrue(os.path.isabs(coarse_root_value))
            self.assertEqual(
                os.path.normpath(coarse_root_value),
                coarse_root_value,
            )
            self.assertTrue(candidate_value.isascii())
            self.assertTrue(candidate_value.isprintable())
            self.assertTrue(os.path.isabs(candidate_value))
            self.assertEqual(
                os.path.normpath(candidate_value),
                candidate_value,
            )
            self.assertNotIn(candidate_value, original)
            self.assertEqual(
                os.path.commonpath(
                    (candidate_value, coarse_root_value)
                ),
                coarse_root_value,
            )
            relative = candidate.relative_to(coarse_root)
            self.assertTrue(relative.parts)
            self.assertNotIn("..", relative.parts)

            mutated = list(original)
            mutated[index] = candidate_value
            self.assertEqual(len(mutated), 5)
            self.assertEqual(len(set(mutated)), 5)
            for canonical in mutated:
                self.assertIs(type(canonical), str)
                self.assertTrue(canonical.isascii())
                self.assertTrue(canonical.isprintable())
                self.assertTrue(os.path.isabs(canonical))
                self.assertEqual(
                    os.path.normpath(canonical),
                    canonical,
                )
            replacement_path = ("startup", "worker_sys_path", index)
            replacements = {replacement_path: candidate_value}
            self.assertEqual(set(replacements), {replacement_path})
            self.assertNotEqual(candidate_value, original[index])
            return replacements

