        def strict_progress_bool_mutation(record, selected_field):
            expected_by_field = {
                "committed_epoch": {
                    "accepted_global_agent_step": 0,
                    "attempted_update_index": None,
                    "committed_epoch": False,
                    "learner_disposition": "discarded",
                    "rollout": None,
                    "volatile_global_agent_step": 0,
                },
                "accepted_global_agent_step": {
                    "accepted_global_agent_step": False,
                    "attempted_update_index": None,
                    "committed_epoch": 0,
                    "learner_disposition": "discarded",
                    "rollout": None,
                    "volatile_global_agent_step": 0,
                },
                "attempted_update_index": {
                    "accepted_global_agent_step": 0,
                    "attempted_update_index": False,
                    "committed_epoch": 0,
                    "learner_disposition": "discarded",
                    "rollout": None,
                    "volatile_global_agent_step": 32768,
                },
                "volatile_global_agent_step": {
                    "accepted_global_agent_step": 0,
                    "attempted_update_index": None,
                    "committed_epoch": 0,
                    "learner_disposition": "discarded",
                    "rollout": None,
                    "volatile_global_agent_step": False,
                },
            }
            self.assertIn(selected_field, expected_by_field)
            source_progress = record["progress"]
            self.assertEqual(
                tuple(sorted(source_progress)),
                WORKER_PROGRESS_FIELDS,
            )
            self.assertIsNone(source_progress["rollout"])
            expected = expected_by_field[selected_field]
            replacements = {
                ("progress", field): copy.deepcopy(value)
                for field, value in expected.items()
                if type(source_progress[field]) is not type(value)
                or source_progress[field] != value
            }
            expected_paths = {
                "committed_epoch": {
                    ("progress", "accepted_global_agent_step"),
                    ("progress", "committed_epoch"),
                    ("progress", "volatile_global_agent_step"),
                },
                "accepted_global_agent_step": {
                    ("progress", "accepted_global_agent_step"),
                    ("progress", "committed_epoch"),
                    ("progress", "volatile_global_agent_step"),
                },
                "attempted_update_index": {
                    ("progress", "accepted_global_agent_step"),
                    ("progress", "attempted_update_index"),
                    ("progress", "committed_epoch"),
                    ("progress", "volatile_global_agent_step"),
                },
                "volatile_global_agent_step": {
                    ("progress", "accepted_global_agent_step"),
                    ("progress", "committed_epoch"),
                    ("progress", "volatile_global_agent_step"),
                },
            }
            self.assertEqual(set(replacements), expected_paths[selected_field])
            projected = copy.deepcopy(source_progress)
            for (_progress, field), value in replacements.items():
                projected[field] = copy.deepcopy(value)
            self.assertEqual(projected, expected)
            self.assertIs(projected[selected_field], False)
            numeric_fields = (
                "accepted_global_agent_step",
                "attempted_update_index",
                "committed_epoch",
                "volatile_global_agent_step",
            )
            self.assertEqual(
                [
                    field
                    for field in numeric_fields
                    if type(projected[field]) is bool
                ],
                [selected_field],
            )
            self.assertTrue(
                all(
                    value is None or isinstance(value, int)
                    for value in (
                        projected[field] for field in numeric_fields
                    )
                )
            )
            self.assertIn(projected["committed_epoch"], range(2957))
            self.assertIn(
                projected["accepted_global_agent_step"],
                range(96_862_209),
            )
            self.assertIn(
                projected["volatile_global_agent_step"],
                range(96_862_209),
            )
            attempted = projected["attempted_update_index"]
            if attempted is None:
                self.assertEqual(
                    projected["volatile_global_agent_step"],
                    projected["accepted_global_agent_step"],
                )
            else:
                self.assertIn(attempted, range(2956))
                self.assertEqual(attempted, projected["committed_epoch"])
                self.assertEqual(
                    projected["volatile_global_agent_step"],
                    projected["accepted_global_agent_step"] + 32768,
                )
            self.assertEqual(
                projected["accepted_global_agent_step"],
                projected["committed_epoch"] * 32768,
            )
            self.assertEqual(projected["learner_disposition"], "discarded")
            self.assertIsNone(projected["rollout"])
            return {"replacements": replacements}

