    def test_controller_and_verdict_handoffs_bind_exact_intent_digest_and_paths(
        self,
    ) -> None:
        cases = (
            (
                _controller_handoff_record(),
                _controller_intent_record(),
                CONTROLLER_HANDOFF_SCHEMA,
                CONTROLLER_HANDOFF_FIELDS,
                "pilot.publish-intent." + ("e" * 32) + "/receipt.json",
                "pilot.controller-handoff/record.json",
            ),
            (
                _verdict_handoff_record(),
                _verdict_intent_record(),
                VERDICT_HANDOFF_SCHEMA,
                VERDICT_HANDOFF_FIELDS,
                (
                    "pilot.verify-publication."
                    + ("f" * 32)
                    + "/receipt.json"
                ),
                "pilot.verdict-handoff/record.json",
            ),
        )
        for record, intent, schema, fields, intent_path, handoff_path in cases:
            with self.subTest(schema=schema):
                self.assertEqual(tuple(sorted(record)), fields)
                self.assertEqual(record["schema"], schema)
                self.assertEqual(record["status"], "prospective")
                self.assertEqual(record["intent_receipt_path"], intent_path)
                self.assertEqual(record["external_handoff_path"], handoff_path)
                self.assertEqual(
                    record["intent_receipt_sha256"],
                    hashlib.sha256(
                        _canonical_json_fixture(intent)
                    ).hexdigest(),
                )
                canonical = _canonical_json_fixture(record)
                frame = struct.pack(">I", len(canonical)) + canonical
                overrides = {
                    "expected_schema": schema,
                    "expected_fields": fields,
                }
                decoded, received = self._read_handoff(
                    frame,
                    **overrides,
                )
                self.assertEqual(decoded, record)
                self.assertEqual(received, canonical)

    def test_controller_and_verdict_results_are_exact_and_status_closed(
        self,
    ) -> None:
        for status in PUBLICATION_RESULT_STATUSES:
            cases = (
                (
                    _controller_result_record(status),
                    CONTROLLER_RESULT_SCHEMA,
                    CONTROLLER_RESULT_FIELDS,
                ),
                (
                    _verdict_result_record(status),
                    VERDICT_RESULT_SCHEMA,
                    VERDICT_RESULT_FIELDS,
                ),
            )
            for result, schema, fields in cases:
                with self.subTest(status=status, schema=schema):
                    self.assertEqual(tuple(sorted(result)), fields)
                    read_fd, write_fd = os.pipe()
                    try:
                        emitted = (
                            self.protocol.write_publication_result_channel(
                                write_fd,
                                result=result,
                                expected_schema=schema,
                                expected_fields=fields,
                            )
                        )
                        write_fd = None
                        self.assertEqual(
                            emitted,
                            _canonical_json_fixture(result),
                        )
                    finally:
                        _close_fd(write_fd)
                        _close_fd(read_fd)
        for invalid in ("prospective", "failed", "", None):
            result = _controller_result_record()
            result["publication_status"] = invalid
            with self.subTest(invalid=invalid):
                read_fd, write_fd = os.pipe()
                try:
                    with self.assertRaises(self.protocol.ProtocolError):
                        self.protocol.write_publication_result_channel(
                            write_fd,
                            result=result,
                            expected_schema=CONTROLLER_RESULT_SCHEMA,
                            expected_fields=CONTROLLER_RESULT_FIELDS,
                        )
                finally:
                    _close_fd(write_fd)
                    _close_fd(read_fd)

