    def test_high_level_publication_signatures_are_exact_and_not_public_cli_overrides(
        self,
    ) -> None:
        expected = (
            (
                self.protocol.publish_payload_leaf,
                (
                    "operations",
                    "relative_path",
                    "payload",
                    "semantic_sha256",
                ),
            ),
            (
                self.protocol.publish_checkpoint_leaf,
                (
                    "operations",
                    "update",
                    "raw_checkpoint",
                    "tensor_sha256",
                ),
            ),
            (
                self.protocol.read_handoff_channel,
                (
                    "read_fd",
                    "deadline",
                    "expected_schema",
                    "expected_fields",
                    "monotonic",
                    "wait_readable",
                ),
            ),
            (
                self.protocol.read_publication_ack_channel,
                (
                    "read_fd",
                    "deadline",
                    "canonical_record_bytes",
                    "monotonic",
                    "wait_readable",
                ),
            ),
            (
                self.protocol.write_publication_result_channel,
                (
                    "write_fd",
                    "result",
                    "expected_schema",
                    "expected_fields",
                ),
            ),
            (
                self.protocol.read_publication_result_channel,
                (
                    "read_fd",
                    "deadline",
                    "expected_schema",
                    "expected_fields",
                    "monotonic",
                    "wait_readable",
                ),
            ),
            (
                _runner()._run_controller_publication_child,
                (
                    "operations",
                    "deadline",
                    "artifact_basename",
                    "evidence_manifest_sha256",
                    "protocol_sha256",
                    "source_commit",
                ),
            ),
            (
                _runner()._supervise_controller_publication,
                (
                    "operations",
                    "deadline",
                    "artifact_basename",
                    "artifact_path",
                    "evidence_manifest_sha256",
                    "protocol_sha256",
                    "source_commit",
                ),
            ),
            (
                _verifier()._run_verdict_publication_child,
                (
                    "operations",
                    "deadline",
                    "artifact_basename",
                    "evidence_manifest_sha256",
                    "expected_verdict_sha256",
                    "protocol_sha256",
                    "source_commit",
                ),
            ),
            (
                _verifier()._supervise_verdict_publication,
                (
                    "operations",
                    "deadline",
                    "artifact_basename",
                    "artifact_path",
                    "evidence_manifest_sha256",
                    "expected_verdict_sha256",
                    "protocol_sha256",
                    "source_commit",
                ),
            ),
        )
        for function, names in expected:
            with self.subTest(function=function.__name__):
                signature = inspect.signature(function)
                self.assertEqual(tuple(signature.parameters), names)
                for name in names[1:]:
                    self.assertEqual(
                        signature.parameters[name].kind,
                        inspect.Parameter.KEYWORD_ONLY,
                    )
        for module in (_runner(), _verifier()):
            self.assertEqual(tuple(inspect.signature(module.main).parameters), ("argv",))

