@requires_implementation
class F5RecurrentPpoTraceAndResultsContract(unittest.TestCase):
    def setUp(self) -> None:
        self.protocol = _protocol()
        self.manifest = self.protocol.load_protocol_manifest()
        self.rows, self.trace_bytes = _training_trace_fixture()
        self.results, self.bitsets = _results_fixture(self.manifest)

    def test_valid_full_trace_and_complete_evaluation_topology(self) -> None:
        self.assertEqual(len(self.rows), 2956)
        self.assertEqual(self.trace_bytes.count(b"\n"), 2956)
        self.assertTrue(self.trace_bytes.endswith(b"\n"))
        self.assertEqual(
            [row["update_index"] for row in self.rows],
            list(range(2956)),
        )
        self.assertEqual(
            [row["committed_epoch"] for row in self.rows],
            list(range(1, 2957)),
        )
        self.assertEqual(
            self.rows[-1]["global_agent_step"],
            96862208,
        )
        self.assertEqual(
            self.rows[-1]["episodes"]["cumulative"],
            6053888,
        )
        self.assertEqual(
            [
                row["committed_epoch"]
                for row in self.rows
                if row["parameters"]["checkpoint_update"]
            ],
            list(CHECKPOINT_UPDATES[1:]),
        )
        self.assertEqual(self.rows[1]["objective"]["events"], 2)
        self.assertEqual(
            self.rows[1]["objective"]["successful_episodes"],
            1,
        )
        self.assertEqual(
            self.rows[-1]["objective"]["cumulative_events"],
            2,
        )
        self.assertEqual(
            self.rows[-1]["objective"][
                "cumulative_successful_episodes"
            ],
            1,
        )
        self.assertEqual(
            self.rows[1]["objective"]["first_update"],
            1,
        )
        self.assertIsNotNone(
            self.rows[1]["parameters"]["pre_objective_sha256"]
        )
        self.assertEqual(
            self.rows[1]["parameters"]["pre_objective_sha256"],
            self.rows[0]["parameters"]["canonical_sha256"],
        )
        self.assertTrue(
            all(
                row["parameters"]["pre_objective_sha256"] is None
                for index, row in enumerate(self.rows)
                if index != 1
            )
        )
        self.assertEqual(
            self.rows[0]["schedule"]["entropy_coefficient"],
            _binary32(0.02),
        )
        self.assertEqual(
            self.rows[0]["schedule"]["learning_rate"],
            0.0006,
        )
        self.assertGreater(
            self.rows[100]["schedule"]["entropy_coefficient"],
            self.rows[2000]["schedule"]["entropy_coefficient"],
        )
        self.assertGreater(
            self.rows[100]["schedule"]["learning_rate"],
            self.rows[2000]["schedule"]["learning_rate"],
        )

        evaluations = self.results["evaluations"]
        self.assertEqual(
            [record["update"] for record in evaluations],
            list(CHECKPOINT_UPDATES),
        )
        self.assertEqual(len(evaluations), 6)
        self.assertTrue(
            all(len(record["seeds"]) == 8 for record in evaluations)
        )
        self.assertEqual(
            sum(len(record["seeds"]) for record in evaluations),
            48,
        )
        repeat = self.results["checkpoint_zero_repeat"]
        self.assertEqual(len(repeat["seeds"]), 8)
        self.assertEqual(len(self.bitsets), 56)
        for evaluation in evaluations:
            self.assertEqual(evaluation["episodes"], 262144)
            self.assertEqual(
                evaluation["successes"],
                sum(seed["successes"] for seed in evaluation["seeds"]),
            )
            self.assertEqual(
                evaluation["wilson95"],
                _wilson95_fixture(
                    evaluation["successes"],
                    evaluation["episodes"],
                ),
            )
            self.assertEqual(
                [seed["seed_index"] for seed in evaluation["seeds"]],
                list(range(8)),
            )
            self.assertEqual(
                [seed["action_seed"] for seed in evaluation["seeds"]],
                list(EVALUATION_ACTION_SEEDS),
            )
            for seed in evaluation["seeds"]:
                raw = self.bitsets[seed["bitset_path"]]
                self.assertEqual(len(raw), 4096)
                self.assertEqual(
                    seed["bitset_sha256"],
                    hashlib.sha256(raw).hexdigest(),
                )
                self.assertEqual(
                    seed["wilson95"],
                    _wilson95_fixture(seed["successes"], 32768),
                )
        for primary, repeated in zip(
            evaluations[0]["seeds"],
            repeat["seeds"],
            strict=True,
        ):
            self.assertEqual(
                self.bitsets[primary["bitset_path"]],
                self.bitsets[repeated["bitset_path"]],
            )
            self.assertEqual(primary["bitset_sha256"], repeated["bitset_sha256"])
            self.assertNotEqual(
                primary["bitset_semantic_sha256"],
                repeated["bitset_semantic_sha256"],
            )
        paired = self.results["paired_final_vs_initial"]
        self.assertEqual(
            paired["both"]
            + paired["final_only"]
            + paired["initial_only"]
            + paired["neither"],
            paired["episodes"],
        )
        self.assertEqual(
            paired["net_final_only"],
            paired["final_only"] - paired["initial_only"],
        )
        self.assertEqual(
            self.results["training"]["objective_events"],
            self.rows[-1]["objective"]["cumulative_events"],
        )
        self.assertEqual(
            self.results["training"]["successful_episodes"],
            self.rows[-1]["objective"][
                "cumulative_successful_episodes"
            ],
        )

        self.protocol.validate_training_trace(
            self.trace_bytes,
            self.manifest,
        )
        self.protocol.validate_results(
            self.results,
            self.manifest,
            trace_rows=self.rows,
            bitsets=self.bitsets,
        )

    def test_every_committed_row_requires_fresh_nonnull_parameter_telemetry(
        self,
    ) -> None:
        registry = self.manifest["artifact"]["schemas"]
        row_schema = registry["roots"]["training-trace.jsonl"]
        fields = (
            "canonical_sha256",
            "norm",
            "drift_from_initial",
        )
        self.assertEqual(len(self.rows), 2956)
        for index, row in enumerate(self.rows):
            parameters = row["parameters"]
            with self.subTest(index=index, phase="positive"):
                self.assertEqual(
                    set(parameters),
                    {
                        "canonical_sha256",
                        "checkpoint_update",
                        "drift_from_initial",
                        "norm",
                        "pre_objective_sha256",
                    },
                )
                self.assertRegex(
                    parameters["canonical_sha256"],
                    r"^[0-9a-f]{64}$",
                )
                self.assertIs(type(parameters["norm"]), float)
                self.assertIs(
                    type(parameters["drift_from_initial"]),
                    float,
                )
                self.assertTrue(math.isfinite(parameters["norm"]))
                self.assertTrue(
                    math.isfinite(parameters["drift_from_initial"])
                )
                self.assertGreaterEqual(parameters["norm"], 0.0)
                self.assertGreaterEqual(
                    parameters["drift_from_initial"],
                    0.0,
                )
                self.protocol.validate_schema(row, row_schema, registry)

            mutated = copy.deepcopy(row)
            field = fields[index % len(fields)]
            mutated["parameters"][field] = (
                None if field == "canonical_sha256" else math.inf
            )
            with self.subTest(index=index, phase="negative", field=field):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_schema(
                        mutated,
                        row_schema,
                        registry,
                    )

    def test_fixed_checkpoint_rows_match_independent_raw_l2_and_digest(
        self,
    ) -> None:
        checkpoints = _checkpoint_bytes_fixture()
        initial = checkpoints[0]
        by_epoch = {
            row["committed_epoch"]: row for row in self.rows
        }
        checkpoint_semantics = {
            update: _canonical_tensor_sha256_from_raw_fixture(raw)
            for update, raw in checkpoints.items()
        }
        rows, _raw = _training_trace_fixture(
            {
                update: checkpoint_semantics[update]
                for update in CHECKPOINT_UPDATES[1:]
            },
            {
                update: _checkpoint_parameter_l2_fixture(raw, initial)
                for update, raw in checkpoints.items()
                if update != 0
            },
        )
        by_epoch = {row["committed_epoch"]: row for row in rows}
        for update in CHECKPOINT_UPDATES[1:]:
            parameters = by_epoch[update]["parameters"]
            expected_l2 = _checkpoint_parameter_l2_fixture(
                checkpoints[update],
                initial,
            )
            with self.subTest(update=update):
                self.assertEqual(
                    parameters["canonical_sha256"],
                    checkpoint_semantics[update],
                )
                self.assertEqual(
                    struct.pack(">d", parameters["norm"]),
                    struct.pack(">d", expected_l2["norm"]),
                )
                self.assertEqual(
                    struct.pack(
                        ">d",
                        parameters["drift_from_initial"],
                    ),
                    struct.pack(
                        ">d",
                        expected_l2["drift_from_initial"],
                    ),
                )

    def test_trace_rejects_representative_one_axis_semantic_mutations(
        self,
    ) -> None:
        mutations = []

        def mutate_row(name, index, dotted, value):
            rows = list(self.rows)
            row = copy.deepcopy(rows[index])
            owner = row
            components = dotted.split(".")
            for component in components[:-1]:
                owner = owner[component]
            owner[components[-1]] = value
            rows[index] = row
            mutations.append((name, rows))

        mutations.append(("missing-last-row", self.rows[:-1]))
        mutate_row("update-index", 100, "update_index", 101)
        mutate_row("committed-epoch", 100, "committed_epoch", 100)
        mutate_row(
            "global-agent-step",
            100,
            "global_agent_step",
            self.rows[100]["global_agent_step"] + 1,
        )
        mutate_row(
            "episode-cumulative",
            100,
            "episodes.cumulative",
            self.rows[100]["episodes"]["cumulative"] + 2048,
        )
        mutate_row(
            "objective-cumulative",
            2,
            "objective.cumulative_events",
            1,
        )
        mutate_row(
            "event-success-conflation",
            1,
            "objective.successful_episodes",
            2,
        )
        mutate_row(
            "first-update",
            2,
            "objective.first_update",
            2,
        )
        mutate_row(
            "checkpoint-schedule",
            511,
            "parameters.checkpoint_update",
            False,
        )
        mutate_row(
            "entropy-schedule",
            100,
            "schedule.entropy_coefficient",
            self.rows[100]["schedule"]["entropy_coefficient"] + 1e-9,
        )
        mutate_row(
            "learning-rate-schedule",
            100,
            "schedule.learning_rate",
            self.rows[100]["schedule"]["learning_rate"] + 1e-9,
        )
        mutate_row(
            "touchdown-reconciliation",
            1,
            "rollout.integrity.reward_components.touchdown",
            1.0,
        )
        mutate_row(
            "td-log-crosscheck",
            1,
            "rollout.td_log_crosscheck",
            False,
        )
        for name, rows in mutations:
            raw = b"".join(
                _canonical_json_fixture(row)
                for row in rows
            )
            with self.subTest(name=name):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_training_trace(
                        raw,
                        self.manifest,
                    )

    def test_every_hard_integrity_leaf_rejects_independently(self) -> None:
        baseline = self.rows[0]
        integrity = baseline["rollout"]["integrity"]
        mutations = []
        for key, value in integrity.items():
            if key == "reward_components":
                for component, component_value in value.items():
                    self.assertEqual(component_value, 0.0)
                    mutations.append(
                        (
                            "reward_components." + component,
                            ("rollout", "integrity", key, component),
                            1.0,
                        )
                    )
                continue
            if type(value) is bool:
                replacement = not value
            elif type(value) is int:
                replacement = value + 1
            elif type(value) is float:
                replacement = value + 1.0
            else:
                self.fail("unowned hard-integrity leaf: " + key)
            mutations.append(
                (key, ("rollout", "integrity", key), replacement)
            )
        for key in (
            "reward_contract",
            "tail_consumed",
            "td_log_crosscheck",
            "terminal_contract",
        ):
            mutations.append(
                (key, ("rollout", key), False)
            )

        suffix = self.trace_bytes[len(_canonical_json_fixture(baseline)) :]
        self.assertEqual(
            len(mutations),
            len(ROLLOUT_INTEGRITY_KEYS)
            - 1
            + len(REWARD_COMPONENT_KEYS)
            + 4,
        )
        for name, path, replacement in mutations:
            row = copy.deepcopy(baseline)
            owner = row
            for component in path[:-1]:
                owner = owner[component]
            owner[path[-1]] = replacement
            raw = _canonical_json_fixture(row) + suffix
            with self.subTest(name=name):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_training_trace(
                        raw,
                        self.manifest,
                    )

