    def test_real_68_then_69_file_artifact_validates_positive(self) -> None:
        with tempfile.TemporaryDirectory(
            prefix="f5-positive-layout-"
        ) as tmp:
            artifact = pathlib.Path(tmp) / "artifact"
            _materialize_artifact_fixture(
                artifact,
                self.bundle,
                post_verdict=False,
            )
            validated_pre = self.protocol.validate_evidence_manifest(
                artifact,
                copy.deepcopy(self.bundle["evidence_manifest"]),
            )
            self.assertEqual(
                validated_pre["protocol_sha256"],
                self.bundle["protocol_sha256"],
            )
            verdict_path = artifact / "verdict.json"
            verdict_path.write_bytes(self.bundle["verdict_bytes"])
            verdict_path.chmod(0o600)
            self.assertEqual(
                sum(path.is_file() for path in artifact.rglob("*")),
                69,
            )
            validated_post = self.protocol.validate_final_evidence(
                artifact,
                self.bundle["verdict_sha256"],
            )
            self.assertTrue(validated_post["accepted"])
            self.assertEqual(
                validated_post["source_commit"],
                self.source_identity["commit"],
            )
            self.assertEqual(
                validated_post["protocol_sha256"],
                self.bundle["protocol_sha256"],
            )
            self.assertEqual(
                validated_post["learning_outcome"],
                "positive-fixed-instance-acquisition-signal",
            )

