    def test_positive_layout_baseline_precedes_materialized_path_failures(
        self,
    ) -> None:
        for mutation in ("missing", "extra", "symlink", "hardlink"):
            with tempfile.TemporaryDirectory(
                prefix="f5-materialized-layout-"
            ) as tmp:
                root = pathlib.Path(tmp)
                artifact = root / "artifact"
                _materialize_artifact_fixture(
                    artifact,
                    self.bundle,
                    post_verdict=False,
                )
                evidence = copy.deepcopy(
                    self.bundle["evidence_manifest"]
                )
                self.protocol.validate_evidence_manifest(
                    artifact,
                    evidence,
                )
                target = artifact / "results.json"
                if mutation == "missing":
                    target.unlink()
                elif mutation == "extra":
                    extra = artifact / "extra.json"
                    extra.write_bytes(b"{}\n")
                    extra.chmod(0o600)
                elif mutation == "symlink":
                    target.unlink()
                    target.symlink_to("protocol.json")
                else:
                    raw = target.read_bytes()
                    target.unlink()
                    anchor = root / "hardlink-anchor"
                    anchor.write_bytes(raw)
                    anchor.chmod(0o600)
                    os.link(anchor, target)
                with self.subTest(mutation=mutation):
                    with self.assertRaises(self.protocol.ProtocolError):
                        self.protocol.validate_evidence_manifest(
                            artifact,
                            evidence,
                        )

